/**
 * LCRH Report Export Utility  —  PDF + Word (.docx)
 * ─────────────────────────────────────────────────
 * All exports include:
 *   • LCRH logo  (public/icons/lcrh-logo.png  OR  icon-512.png fallback)
 *   • Hospital letterhead
 *   • Signature block  (Prepared By / Checked By / Reviewed By)
 *
 * Access restricted to superuser role — enforced in calling components.
 */

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import {
  Document, Packer, Paragraph, Table, TableRow, TableCell,
  TextRun, ImageRun, AlignmentType, WidthType,
  BorderStyle, ShadingType, convertInchesToTwip,
} from "docx";
import { saveAs } from "file-saver";

/* ─── Constants ─────────────────────────────────────────────────────────── */
const NAVY   = [31, 56, 100];   // #1F3864  (RGB for jsPDF)
const GOLD   = [201, 168, 76];  // #C9A84C
const LGRAY  = [243, 244, 246]; // #F3F4F6  light row alternate
const WHITE  = [255, 255, 255];

const NAVY_HEX  = "1F3864";
const GOLD_HEX  = "C9A84C";
const LGRAY_HEX = "F3F4F6";
const ALTROW    = "EFF6FF";    // very light blue alternate rows
const FOOTROW   = "EFF6FF";   // footer row
const WHITE_HEX = "FFFFFF";

const nowStr = () =>
  new Date().toLocaleDateString("en-KE", { year: "numeric", month: "long", day: "numeric" });

const fmtKES = n => `KES ${Number(n || 0).toLocaleString("en-KE")}`;

/* ─── Logo Fetch ────────────────────────────────────────────────────────── */
async function fetchLogo() {
  const paths = [
    `${process.env.PUBLIC_URL}/icons/lcrh-logo.png`,
    `${process.env.PUBLIC_URL}/icons/icon-512.png`,
  ];
  for (const path of paths) {
    try {
      const res = await fetch(path);
      if (!res.ok) continue;
      const buf = await res.arrayBuffer();
      const b64 = `data:image/png;base64,${btoa(String.fromCharCode(...new Uint8Array(buf)))}`;
      return { arrayBuffer: buf, base64: b64 };
    } catch { /* try next */ }
  }
  return null;
}

/* ══════════════════════════════════════════════════════════════════════════
   PDF  HELPERS
   ══════════════════════════════════════════════════════════════════════════ */

/**
 * Draw the LCRH letterhead at the top of every PDF page.
 * If the logo is the wide banner (lcrh-logo.png) it is displayed full-width.
 * Returns the Y position below the header.
 */
function drawPdfHeader(doc, logo, title, period) {
  const pw = doc.internal.pageSize.getWidth();
  let y = 6;

  if (logo) {
    // Banner is 808×164 px  →  aspect 4.93:1
    const logoW = pw - 16;           // full usable width (e.g. 194mm on A4)
    const logoH = logoW / 4.93;     // proportional height ≈ 39mm
    doc.addImage(logo.base64, "PNG", 8, y, logoW, logoH);
    y += logoH + 2;
  } else {
    // Fallback: navy text header when no logo
    doc.setFillColor(...NAVY);
    doc.rect(0, 0, pw, 26, "F");
    doc.setTextColor(...WHITE);
    doc.setFont("helvetica", "bold"); doc.setFontSize(12);
    doc.text("LODWAR COUNTY REFERRAL HOSPITAL", 8, 11);
    doc.setFont("helvetica", "normal"); doc.setFontSize(8.5);
    doc.text("Turkana County Government — Finance Department", 8, 18);
    doc.setTextColor(0, 0, 0);
    y = 30;
  }

  // Gold rule
  doc.setDrawColor(...GOLD);
  doc.setLineWidth(0.8);
  doc.line(8, y, pw - 8, y);
  y += 3;

  // Report title + period on same line
  doc.setFont("helvetica", "bold"); doc.setFontSize(10); doc.setTextColor(...NAVY);
  doc.text(title, 8, y + 5);
  doc.setFont("helvetica", "normal"); doc.setFontSize(8); doc.setTextColor(100, 100, 100);
  doc.text(period, pw - 8, y + 5, { align: "right" });

  // Light underline
  doc.setDrawColor(220, 220, 220); doc.setLineWidth(0.3);
  doc.line(8, y + 7, pw - 8, y + 7);
  doc.setTextColor(0, 0, 0);

  return y + 12;
}

/** Draw PDF footer on every page. */
function addPdfFooter(doc) {
  const pw = doc.internal.pageSize.getWidth();
  const ph = doc.internal.pageSize.getHeight();
  const pages = doc.internal.getNumberOfPages();
  for (let i = 1; i <= pages; i++) {
    doc.setPage(i);
    doc.setFontSize(7.5);
    doc.setTextColor(150, 150, 150);
    doc.text(
      `Lodwar County Referral Hospital  |  Auto-generated: ${nowStr()}  |  CONFIDENTIAL`,
      8, ph - 6
    );
    doc.text(`Page ${i} / ${pages}`, pw - 8, ph - 6, { align: "right" });
    doc.setDrawColor(220, 220, 220);
    doc.setLineWidth(0.3);
    doc.line(8, ph - 9, pw - 8, ph - 9);
  }
}

/** Draw the 3-column signature block at the current Y. */
function drawPdfSignatures(doc, y, { preparedBy, checkedBy, reviewedBy }) {
  const pw  = doc.internal.pageSize.getWidth();
  const bw  = (pw - 16) / 3;
  const bh  = 32;
  const labels = [
    { role: "Prepared By (Finance Officer)", name: preparedBy || "" },
    { role: "Checked By (Administration)",  name: checkedBy  || "" },
    { role: "Reviewed By (Superuser)",       name: reviewedBy || "" },
  ];

  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(...NAVY);
  doc.text("AUTHORISATION", 8, y);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(0, 0, 0);
  y += 4;

  labels.forEach((sig, i) => {
    const x = 8 + i * (bw + 2);
    // Box
    doc.setFillColor(...LGRAY);
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.3);
    doc.roundedRect(x, y, bw, bh, 2, 2, "FD");

    // Role label
    doc.setFontSize(7.5);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(...NAVY);
    doc.text(sig.role, x + 4, y + 7);

    // Name
    doc.setFont("helvetica", "normal");
    doc.setTextColor(60, 60, 60);
    doc.setFontSize(8);
    doc.text(`Name:  ${sig.name || "________________________"}`, x + 4, y + 14);

    // Signature line
    doc.setTextColor(120, 120, 120);
    doc.setFontSize(7.5);
    doc.text("Signature:", x + 4, y + 21);
    doc.setDrawColor(160, 160, 160);
    doc.line(x + 23, y + 21, x + bw - 4, y + 21);

    // Date line
    doc.text("Date:", x + 4, y + 28);
    doc.line(x + 16, y + 28, x + bw - 4, y + 28);
  });
}

