export async function exportRevenuePDF({ selMonth, byStream, monthRecs, total, annualTotal, signatories = {} }) {
  const logo = await fetchLogo();
  const doc  = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });

  let y = drawPdfHeader(doc, logo, "Revenue Collection Report", `Period: ${selMonth}  |  Generated: ${nowStr()}`);

  // KPI row
  const kpis = [
    { label: "Period Revenue",  value: fmtKES(total) },
    { label: "No. of Records",  value: monthRecs.length.toLocaleString() },
    { label: "YTD Total",       value: fmtKES(annualTotal) },
  ];
  const bw = (doc.internal.pageSize.getWidth() - 16) / 3;
  kpis.forEach((k, i) => {
    const x = 8 + i * (bw + 2);
    doc.setFillColor(...LGRAY);
    doc.roundedRect(x, y, bw, 18, 2, 2, "F");
    doc.setFontSize(7.5); doc.setTextColor(107, 114, 128); doc.setFont("helvetica", "normal");
    doc.text(k.label.toUpperCase(), x + 4, y + 7);
    doc.setFontSize(11); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
    doc.text(k.value, x + 4, y + 14);
  });
  y += 22;

  // Stream table
  autoTable(doc, {
    startY: y,
    head:  [["Revenue Stream", "Records", "Amount (KES)", "% Share"]],
    body:   byStream.filter(s => s.count > 0).map(s => [
      s.stream, s.count, s.amount.toLocaleString("en-KE"),
      total > 0 ? `${((s.amount / total) * 100).toFixed(1)}%` : "—",
    ]),
    foot:  [["TOTAL", monthRecs.length, total.toLocaleString("en-KE"), "100%"]],
    headStyles: { fillColor: NAVY, textColor: 255, fontSize: 8.5, fontStyle: "bold" },
    footStyles: { fillColor: LGRAY, textColor: NAVY, fontStyle: "bold", fontSize: 9 },
    alternateRowStyles: { fillColor: [249, 250, 251] },
    columnStyles: { 1: { halign: "center" }, 3: { halign: "center" } },
    styles: { fontSize: 8.5, cellPadding: 3 },
    margin: { left: 8, right: 8 },
  });
  y = (doc.lastAutoTable?.finalY ?? y) + 8;

  // Individual entries table
  if (monthRecs.length > 0) {
    doc.setFontSize(9.5); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
    doc.text(`Individual Entries — ${selMonth}`, 8, y);
    doc.setFont("helvetica", "normal"); doc.setTextColor(0, 0, 0);
    autoTable(doc, {
      startY: y + 4,
      head: [["Date", "Receipt", "Stream", "Description", "Mode", "Amount (KES)", "Collector", "Status"]],
      body: monthRecs.map(r => [
        r.date, r.receipt || "", r.stream, r.description || "",
        r.paymentMode || "", (r.amount || 0).toLocaleString("en-KE"),
        r.collector || "", r.status || "",
      ]),
      headStyles: { fillColor: NAVY, textColor: 255, fontSize: 7.5, fontStyle: "bold" },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      styles: { fontSize: 7.5, cellPadding: 2 },
      margin: { left: 8, right: 8 },
      columnStyles: { 5: { halign: "right" } },
    });
    y = (doc.lastAutoTable?.finalY ?? y) + 10;
  }

  // Check if signature block fits; add page if needed
  if (y + 45 > doc.internal.pageSize.getHeight() - 15) {
    doc.addPage();
    y = 15;
  }
  drawPdfSignatures(doc, y, signatories);

  addPdfFooter(doc);
  doc.save(`LCRH_Revenue_Report_${selMonth}.pdf`);
}

export async function exportInsurancePDF({ reportDate, reportByScheme, reportClaims, reportTotal, signatories = {} }) {
  const logo = await fetchLogo();
  const doc  = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });

  let y = drawPdfHeader(doc, logo, "Insurance Claims Report", `Date: ${reportDate}  |  Generated: ${nowStr()}`);

  // KPI
  const kpis = [
    { label: "Total Claims",    value: String(reportClaims.length) },
    { label: "Total Claimed",   value: fmtKES(reportTotal) },
    { label: "Approved / Paid", value: String(reportClaims.filter(c => ["Approved","Paid"].includes(c.status)).length) },
    { label: "Rejected",        value: String(reportClaims.filter(c => c.status === "Rejected").length) },
  ];
  const kbw = (doc.internal.pageSize.getWidth() - 16) / 4;
  kpis.forEach((k, i) => {
    const x = 8 + i * (kbw + 1.3);
    doc.setFillColor(...LGRAY);
    doc.roundedRect(x, y, kbw, 18, 2, 2, "F");
    doc.setFontSize(7); doc.setTextColor(107, 114, 128); doc.setFont("helvetica", "normal");
    doc.text(k.label.toUpperCase(), x + 3, y + 7);
    doc.setFontSize(11); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
    doc.text(k.value, x + 3, y + 14);
  });
  y += 22;

  autoTable(doc, {
    startY: y,
    head: [["Scheme","Claims","Claimed (KES)","Approved (KES)","Paid (KES)","Rejected (KES)"]],
    body: reportByScheme.filter(s => s.count > 0).map(s => [
      s.scheme, s.count,
      s.amount.toLocaleString("en-KE"), s.approved.toLocaleString("en-KE"),
      s.paid.toLocaleString("en-KE"),   s.rejected.toLocaleString("en-KE"),
    ]),
    foot: [["TOTAL", reportClaims.length, reportTotal.toLocaleString("en-KE"), "", "", ""]],
    headStyles: { fillColor: NAVY, textColor: 255, fontSize: 8, fontStyle: "bold" },
    footStyles: { fillColor: LGRAY, textColor: NAVY, fontStyle: "bold" },
    alternateRowStyles: { fillColor: [249, 250, 251] },
    columnStyles: { 1:{ halign:"center" }, 2:{ halign:"right" }, 3:{ halign:"right" }, 4:{ halign:"right" }, 5:{ halign:"right" } },
    styles: { fontSize: 8, cellPadding: 3 },
    margin: { left: 8, right: 8 },
  });
  y = (doc.lastAutoTable?.finalY ?? y) + 8;

  if (reportClaims.length > 0) {
    doc.setFontSize(9.5); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
    doc.text(`Individual Claims — ${reportDate}`, 8, y);
    doc.setFont("helvetica", "normal"); doc.setTextColor(0, 0, 0);
    autoTable(doc, {
      startY: y + 4,
      head: [["Patient","Scheme","Service","Type","Claim Ref","Claimed (KES)","Status"]],
      body: reportClaims.map(c => [
        c.patientName || "", c.scheme || "", c.service || "",
        c.admissionType || "", c.claimRef || "",
        (c.claimAmount || 0).toLocaleString("en-KE"), c.status || "",
      ]),
      headStyles: { fillColor: NAVY, textColor: 255, fontSize: 7.5, fontStyle: "bold" },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      styles: { fontSize: 7.5, cellPadding: 2 },
      margin: { left: 8, right: 8 },
      columnStyles: { 5: { halign: "right" } },
    });
    y = (doc.lastAutoTable?.finalY ?? y) + 10;
  }

  if (y + 45 > doc.internal.pageSize.getHeight() - 15) { doc.addPage(); y = 15; }
  drawPdfSignatures(doc, y, signatories);
  addPdfFooter(doc);
  doc.save(`LCRH_Insurance_Report_${reportDate}.pdf`);
}

export async function exportRecordsPDF({ records, filters, total, signatories = {} }) {
  const logo = await fetchLogo();
  const doc  = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });

  const filterLabel = [
    filters.fMonth  !== "All" ? `Month: ${filters.fMonth}`   : "",
    filters.fStream !== "All" ? `Stream: ${filters.fStream}` : "",
    filters.fStatus !== "All" ? `Status: ${filters.fStatus}` : "",
    filters.search  ? `Search: "${filters.search}"` : "",
  ].filter(Boolean).join("  |  ") || "All records";

  let y = drawPdfHeader(doc, logo, "Revenue Records Export", `Filter: ${filterLabel}  |  Generated: ${nowStr()}`);

  // Summary bar
  const pw = doc.internal.pageSize.getWidth();
  doc.setFillColor(...LGRAY);
  doc.rect(8, y, pw - 16, 12, "F");
  doc.setFontSize(9); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
  doc.text(`${records.length} records  |  Total: ${fmtKES(total)}`, 12, y + 8);
  doc.setFont("helvetica", "normal"); doc.setTextColor(0, 0, 0);
  y += 16;

  autoTable(doc, {
    startY: y,
    head: [["Date","Receipt","Stream","Description","Mode","Amount (KES)","Collector","Status"]],
    body: records.map(r => [
      r.date, r.receipt || "", r.stream, r.description || "",
      r.paymentMode || "", (r.amount || 0).toLocaleString("en-KE"),
      r.collector || "", r.status || "",
    ]),
    foot: [["", "", "", `Total (${records.length} records)`, "", total.toLocaleString("en-KE"), "", ""]],
    headStyles: { fillColor: NAVY, textColor: 255, fontSize: 8, fontStyle: "bold" },
    footStyles: { fillColor: LGRAY, textColor: NAVY, fontStyle: "bold", fontSize: 9 },
    alternateRowStyles: { fillColor: [249, 250, 251] },
    styles: { fontSize: 8, cellPadding: 2.5 },
    margin: { left: 8, right: 8 },
    columnStyles: { 5: { halign: "right" } },
  });
  y = (doc.lastAutoTable?.finalY ?? y) + 10;

  if (y + 45 > doc.internal.pageSize.getHeight() - 15) { doc.addPage(); y = 15; }
  drawPdfSignatures(doc, y, signatories);
  addPdfFooter(doc);
  doc.save(`LCRH_Records_Export_${new Date().toISOString().slice(0,10)}.pdf`);
}

/* ══════════════════════════════════════════════════════════════════════════
   WORD  HELPERS
   ══════════════════════════════════════════════════════════════════════════ */

const noBorder = () => {
  const n = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
  return { top: n, bottom: n, left: n, right: n };
};
const thinBorder = () => {
  const b = { style: BorderStyle.SINGLE, size: 2, color: "E5E7EB" };
  return { top: b, bottom: b, left: b, right: b };
};

/** Build a clean, light-themed docx table. */
function buildDocxTable(columns, rows, foot, widths) {
  const pct = WidthType.PERCENTAGE;

  const makeCell = (text, opts = {}) => {
    const {
      fillHex = WHITE_HEX, bold = false, textColor = "111827",
      align = AlignmentType.LEFT, size = 18, borders = thinBorder(),
    } = opts;
    return new TableCell({
      shading: { fill: fillHex, type: ShadingType.CLEAR },
      borders,
      ...(widths ? {} : {}),
      children: [new Paragraph({
        alignment: align,
        spacing: { before: 60, after: 60 },
        children: [new TextRun({ text: String(text ?? ""), bold, color: textColor, size })],
      })],
    });
  };

  // Header row
  const headRow = new TableRow({
    tableHeader: true,
    children: columns.map((col, i) => new TableCell({
      shading: { fill: NAVY_HEX, type: ShadingType.CLEAR },
      borders: noBorder(),
      width: widths ? { size: widths[i], type: pct } : undefined,
      children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 80, after: 80 },
        children: [new TextRun({ text: String(col), bold: true, color: WHITE_HEX, size: 18 })],
      })],
    })),
  });

  // Data rows
  const dataRows = rows.map((row, ri) =>
    new TableRow({
      children: row.map(cell => makeCell(cell, {
        fillHex: ri % 2 === 1 ? ALTROW : WHITE_HEX,
      })),
    })
  );

  // Footer row
  const footRow = foot ? new TableRow({
    children: foot.map(cell => new TableCell({
      shading: { fill: LGRAY_HEX, type: ShadingType.CLEAR },
      borders: { ...thinBorder(), top: { style: BorderStyle.THICK, size: 6, color: NAVY_HEX } },
      children: [new Paragraph({
        spacing: { before: 80, after: 80 },
        children: [new TextRun({ text: String(cell ?? ""), bold: true, color: NAVY_HEX, size: 20 })],
      })],
    })),
  }) : null;

  return new Table({
    width: { size: 100, type: pct },
    rows: [headRow, ...dataRows, ...(footRow ? [footRow] : [])],
  });
}

/** Build the 3-cell signature table for docx. */
function buildDocxSignatures({ preparedBy, checkedBy, reviewedBy }) {
  const heading = new Paragraph({
    children: [new TextRun({ text: "AUTHORISATION", bold: true, color: NAVY_HEX, size: 22 })],
    spacing: { before: 400, after: 120 },
  });

  const makeSigCell = (roleLabel, name) =>
    new TableCell({
      shading: { fill: "F8FAFC", type: ShadingType.CLEAR },
      borders: thinBorder(),
      margins: { top: convertInchesToTwip(0.08), bottom: convertInchesToTwip(0.08), left: convertInchesToTwip(0.1), right: convertInchesToTwip(0.1) },
      children: [
        new Paragraph({ children: [new TextRun({ text: roleLabel, bold: true, color: NAVY_HEX, size: 18 })], spacing: { after: 80 } }),
        new Paragraph({ children: [new TextRun({ text: `Name:  ${name || ""}`, size: 18, color: "374151" })], spacing: { after: 60 } }),
        new Paragraph({ children: [new TextRun({ text: " ", size: 18 })], spacing: { after: 60 } }),
        new Paragraph({ children: [new TextRun({ text: "Signature:  ___________________________", size: 17, color: "9CA3AF" })], spacing: { after: 60 } }),
        new Paragraph({ children: [new TextRun({ text: " ", size: 18 })], spacing: { after: 60 } }),
        new Paragraph({ children: [new TextRun({ text: "Date:  ______________________________", size: 17, color: "9CA3AF" })], spacing: { after: 60 } }),
      ],
    });

  const sigTable = new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    rows: [new TableRow({
      children: [
        makeSigCell("Prepared By (Finance Officer)", preparedBy || ""),
        makeSigCell("Checked By (Administration)",   checkedBy  || ""),
        makeSigCell("Reviewed By (Superuser)",        reviewedBy || ""),
      ],
    })],
  });

  return [heading, sigTable];
}

/** Build the Word letterhead paragraphs. */
async function buildLetterhead(logo, title, subtitle) {
  const children = [];

  if (logo) {
    // Banner is 808×164px → aspect 4.93:1
    // Target width ≈ 670px (fills A4 page between 900-twip margins)
    const logoW = 670;
    const logoH = Math.round(logoW / 4.93); // ≈ 136
    children.push(new Paragraph({
      children: [new ImageRun({
        data: logo.arrayBuffer,
        transformation: { width: logoW, height: logoH },
        type: "png",
      })],
      spacing: { after: 60 },
    }));
  } else {
    // Fallback text header
    children.push(
      new Paragraph({ children: [new TextRun({ text: "LODWAR COUNTY REFERRAL HOSPITAL", bold: true, color: NAVY_HEX, size: 28 })] }),
      new Paragraph({ children: [new TextRun({ text: "Turkana County Government  —  Finance Department", color: "6B7280", size: 18 })], spacing: { after: 60 } }),
    );
  }

  children.push(
    new Paragraph({
      children: [new TextRun({ text: "━".repeat(70), color: GOLD_HEX, size: 14 })],
      spacing: { before: 40, after: 80 },
    }),
    new Paragraph({
      children: [new TextRun({ text: title, bold: true, color: NAVY_HEX, size: 24 })],
    }),
    new Paragraph({
      children: [new TextRun({ text: subtitle, color: "6B7280", size: 17 })],
      spacing: { after: 200 },
    })
  );

  return children;
}

/** Build a clean KPI row as a light-filled table. */
function buildKpiTable(items) {
  const cols = items.map(k =>
    new TableCell({
      shading: { fill: "EFF6FF", type: ShadingType.CLEAR },
      borders: thinBorder(),
      margins: { top: convertInchesToTwip(0.06), bottom: convertInchesToTwip(0.06), left: convertInchesToTwip(0.08), right: convertInchesToTwip(0.08) },
      children: [
        new Paragraph({ children: [new TextRun({ text: k.label.toUpperCase(), size: 14, color: "6B7280" })], spacing: { after: 40 } }),
        new Paragraph({ children: [new TextRun({ text: String(k.value), bold: true, color: NAVY_HEX, size: 24 })] }),
      ],
    })
  );

  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    rows: [new TableRow({ children: cols })],
  });
}

