/* ══════════════════════════════════════════════════════════════════════════
   FINANCE  OFFICER  REPORT  —  PDF + Word + CSV
   Combines an individual officer's Revenue collections and Insurance
   claims for a selected period. Access restricted to superuser role —
   enforced in the calling component (Reports.js).
   ══════════════════════════════════════════════════════════════════════════ */

const slugName = n => String(n || "Unassigned").trim().replace(/\s+/g, "_");

export async function exportOfficerPDF({
  officerName, period,
  revenueRecs = [], revenueTotal = 0, revenueByStream = [],
  claims = [], claimsTotal = 0, claimsByScheme = [],
  signatories = {},
}) {
  const logo = await fetchLogo();
  const doc  = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });

  let y = drawPdfHeader(doc, logo, `Finance Officer Report — ${officerName}`, `Period: ${period}  |  Generated: ${nowStr()}`);

  // KPI row
  const kpis = [
    { label: "Revenue Collected", value: fmtKES(revenueTotal) },
    { label: "Revenue Records",   value: revenueRecs.length.toLocaleString() },
    { label: "Claims Submitted",  value: claims.length.toLocaleString() },
    { label: "Claims Amount",     value: fmtKES(claimsTotal) },
  ];
  const kbw = (doc.internal.pageSize.getWidth() - 16) / 4;
  kpis.forEach((k, i) => {
    const x = 8 + i * (kbw + 1.3);
    doc.setFillColor(...LGRAY);
    doc.roundedRect(x, y, kbw, 18, 2, 2, "F");
    doc.setFontSize(7); doc.setTextColor(107, 114, 128); doc.setFont("helvetica", "normal");
    doc.text(k.label.toUpperCase(), x + 3, y + 7);
    doc.setFontSize(10.5); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
    doc.text(k.value, x + 3, y + 14);
  });
  y += 22;

  // Revenue section
  if (revenueRecs.length > 0) {
    doc.setFontSize(10); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
    doc.text("Revenue Collected", 8, y);
    y += 4;
    autoTable(doc, {
      startY: y,
      head: [["Revenue Stream", "Records", "Amount (KES)"]],
      body: revenueByStream.filter(s => s.count > 0).map(s => [s.stream, s.count, s.amount.toLocaleString("en-KE")]),
      foot: [["TOTAL", revenueRecs.length, revenueTotal.toLocaleString("en-KE")]],
      headStyles: { fillColor: NAVY, textColor: 255, fontSize: 8.5, fontStyle: "bold" },
      footStyles: { fillColor: LGRAY, textColor: NAVY, fontStyle: "bold" },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      styles: { fontSize: 8.5, cellPadding: 3 },
      margin: { left: 8, right: 8 },
    });
    y = (doc.lastAutoTable?.finalY ?? y) + 6;

    autoTable(doc, {
      startY: y,
      head: [["Date", "Receipt", "Stream", "Description", "Mode", "Amount (KES)", "Status"]],
      body: revenueRecs.map(r => [
        r.date, r.receipt || "", r.stream, r.description || "",
        r.paymentMode || "", (r.amount || 0).toLocaleString("en-KE"), r.status || "",
      ]),
      headStyles: { fillColor: NAVY, textColor: 255, fontSize: 7.5, fontStyle: "bold" },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      styles: { fontSize: 7.5, cellPadding: 2 },
      margin: { left: 8, right: 8 },
      columnStyles: { 5: { halign: "right" } },
    });
    y = (doc.lastAutoTable?.finalY ?? y) + 10;
  }

  if (y + 40 > doc.internal.pageSize.getHeight() - 15) { doc.addPage(); y = 15; }

  // Claims section
  if (claims.length > 0) {
    doc.setFontSize(10); doc.setFont("helvetica", "bold"); doc.setTextColor(...NAVY);
    doc.text("Insurance Claims Submitted", 8, y);
    y += 4;
    autoTable(doc, {
      startY: y,
      head: [["Scheme", "Claims", "Claimed (KES)"]],
      body: claimsByScheme.filter(s => s.count > 0).map(s => [s.scheme, s.count, s.amount.toLocaleString("en-KE")]),
      foot: [["TOTAL", claims.length, claimsTotal.toLocaleString("en-KE")]],
      headStyles: { fillColor: NAVY, textColor: 255, fontSize: 8.5, fontStyle: "bold" },
      footStyles: { fillColor: LGRAY, textColor: NAVY, fontStyle: "bold" },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      styles: { fontSize: 8.5, cellPadding: 3 },
      margin: { left: 8, right: 8 },
    });
    y = (doc.lastAutoTable?.finalY ?? y) + 6;

    autoTable(doc, {
      startY: y,
      head: [["Date", "Patient", "Scheme", "Claim Ref", "Claimed (KES)", "Status"]],
      body: claims.map(c => [
        c.date, c.patientName || "", c.scheme || "", c.claimRef || "",
        (c.claimAmount || 0).toLocaleString("en-KE"), c.status || "",
      ]),
      headStyles: { fillColor: NAVY, textColor: 255, fontSize: 7.5, fontStyle: "bold" },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      styles: { fontSize: 7.5, cellPadding: 2 },
      margin: { left: 8, right: 8 },
      columnStyles: { 4: { halign: "right" } },
    });
    y = (doc.lastAutoTable?.finalY ?? y) + 10;
  }

  if (revenueRecs.length === 0 && claims.length === 0) {
    doc.setFontSize(9.5); doc.setTextColor(150, 150, 150); doc.setFont("helvetica", "normal");
    doc.text("No revenue or claims activity recorded for this officer in the selected period.", 8, y);
    y += 10;
  }

  if (y + 45 > doc.internal.pageSize.getHeight() - 15) { doc.addPage(); y = 15; }
  drawPdfSignatures(doc, y, signatories);
  addPdfFooter(doc);
  doc.save(`LCRH_Officer_Report_${slugName(officerName)}_${period}.pdf`);
}

