export function exportOfficerCSV({
  officerName, period,
  revenueRecs = [], claims = [],
}) {
  const escape = v => { const s = String(v ?? "").replace(/"/g, '""'); return /[",\n]/.test(s) ? `"${s}"` : s; };
  const revenueTotal = revenueRecs.reduce((s, r) => s + (r.amount || 0), 0);
  const claimsTotal  = claims.reduce((s, c) => s + (c.claimAmount || 0), 0);

  const lines = [];
  lines.push("LCRH Finance Officer Report");
  lines.push(`Officer,${escape(officerName)}`);
  lines.push(`Period,${escape(period)}`);
  lines.push(`Generated,${escape(nowStr())}`);
  lines.push("");
  lines.push("REVENUE COLLECTED");
  lines.push(["Date", "Receipt", "Stream", "Description", "Mode", "Amount (KES)", "Status"].join(","));
  revenueRecs.forEach(r => lines.push(
    [r.date, r.receipt, r.stream, r.description, r.paymentMode, r.amount || 0, r.status].map(escape).join(",")
  ));
  lines.push(`Revenue Total,,,,,${revenueTotal},`);
  lines.push("");
  lines.push("INSURANCE CLAIMS SUBMITTED");
  lines.push(["Date", "Patient", "Scheme", "Claim Ref", "Claimed Amount (KES)", "Status"].join(","));
  claims.forEach(c => lines.push(
    [c.date, c.patientName, c.scheme, c.claimRef, c.claimAmount || 0, c.status].map(escape).join(",")
  ));
  lines.push(`Claims Total,,,,${claimsTotal},`);

  const blob = new Blob([lines.join("\r\n")], { type: "text/csv;charset=utf-8;" });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement("a");
  a.href = url;
  a.download = `LCRH_Officer_Report_${slugName(officerName)}_${period}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}
