import React, { useState } from "react";
import { db } from "../firebase/config";
import { collection, addDoc, serverTimestamp } from "firebase/firestore";
import { useAuth } from "../firebase/AuthContext";

const SERVICES = [
  "Gas Refill","Waste Management","Dental","Wrong Parking","Laboratory",
  "Surgical","CT Scan","Renal","Pharmacy","Morgue","Card","ENT",
  "Orthopedic","Xray","Ultrasound","Special Clinic","Physiotherapy",
  "Eye Unit","Attachment","Other"
];
const WARDS         = ["Surgical Ward","Pediatric Ward","Medical Ward","Maternity Ward","ICU","Amenity"];
const ADMISSION     = ["Outpatient","Inpatient"];
const PAYMENT_MODES = ["Cash","M-PESA","Bank Transfer","Cheque","SHA","AAR","MKL","JUBILEE","OLD MUTUAL","LCT","MTIBA","Waiver","Other"];
const STREAMS       = ["OPD Fees","IPD Charges","Lab Services","Pharmacy","Maternity","Radiology","Other"];

const today      = () => new Date().toISOString().slice(0,10);
const genReceipt = () => `RCP-${Date.now().toString().slice(-6)}`;

const lbl = { fontSize:12, fontWeight:500, color:"#374151", display:"block", marginBottom:5 };
const inp = { width:"100%", boxSizing:"border-box" };

export default function RevenueEntry() {
  const { user, profile } = useAuth();

  const [form, setForm] = useState({
    date:          today(),
    stream:        "OPD Fees",
    service:       "Laboratory",
    admissionType: "Outpatient",
    ward:          "",
    patientName:   "",
    patientNo:     "",
    description:   "",
    totalBill:     "",
    amountPaid:    "",
    amountWaived:  "",
    paymentMode:   "Cash",
    receipt:       genReceipt(),
    // M-PESA fields
    mpesaCode:     "",
    mpesaPhone:    "",
    mpesaPayer:    "",
    // Collector
    collector:     profile?.name || "",
    notes:         "",
  });

  const [busy,  setBusy]  = useState(false);
  const [saved, setSaved] = useState(false);
  const [err,   setErr]   = useState("");

  const set = k => e => setForm(f => ({ ...f, [k]: e.target.value }));

  const totalBill    = parseFloat(form.totalBill)    || 0;
  const amountPaid   = parseFloat(form.amountPaid)   || 0;
  const amountWaived = parseFloat(form.amountWaived) || 0;
  const balance      = totalBill - amountPaid - amountWaived;
  const isMpesa      = form.paymentMode === "M-PESA";

  const submit = async (e) => {
    e.preventDefault();
    if (!form.date || !form.totalBill || !form.description) {
      setErr("Date, description and total bill are required."); return;
    }
    if (amountPaid + amountWaived > totalBill) {
      setErr("Amount paid + waived cannot exceed total bill."); return;
    }
    if (isMpesa && !form.mpesaCode) {
      setErr("M-PESA transaction code is required when payment mode is M-PESA."); return;
    }
    setErr(""); setBusy(true);

    try {
      const record = {
        date:          form.date,
        stream:        form.stream,
        service:       form.service,
        admissionType: form.admissionType,
        ward:          form.admissionType === "Inpatient" ? form.ward : "",
        patientName:   form.patientName.trim(),
        patientNo:     form.patientNo.trim(),
        description:   form.description.trim(),
        totalBill,
        amountPaid,
        amountWaived,
        balance,
        amount:        amountPaid,
        paymentMode:   form.paymentMode,
        receipt:       isMpesa
                         ? form.mpesaCode.trim().toUpperCase()
                         : form.receipt.trim() || genReceipt(),
        collector:     form.collector.trim(),
        notes:         form.notes.trim(),
        status:        "Pending",
        createdBy:     user.uid,
        createdByEmail: user.email,
        createdAt:     serverTimestamp(),
      };

      // Add M-PESA fields if applicable
      if (isMpesa) {
        record.mpesaCode  = form.mpesaCode.trim().toUpperCase();
        record.mpesaPhone = form.mpesaPhone.trim();
        record.mpesaPayer = form.mpesaPayer.trim();
      }

      await addDoc(collection(db, "revenue"), record);

      // Also write to mpesa_transactions collection for separate reporting
      if (isMpesa) {
        await addDoc(collection(db, "mpesa_transactions"), {
          date:        form.date,
          mpesaCode:   form.mpesaCode.trim().toUpperCase(),
          phoneNumber: form.mpesaPhone.trim(),
          payerName:   form.mpesaPayer.trim() || form.patientName.trim(),
          amount:      amountPaid,
          service:     form.service,
          admissionType: form.admissionType,
          patientName: form.patientName.trim(),
          patientNo:   form.patientNo.trim(),
          description: form.description.trim(),
          collector:   form.collector.trim(),
          status:      "Confirmed",
          createdBy:   user.uid,
          createdAt:   serverTimestamp(),
        });
      }

      setSaved(true);
      setForm(f => ({
        ...f,
        description:"", totalBill:"", amountPaid:"", amountWaived:"",
        patientName:"", patientNo:"", notes:"",
        mpesaCode:"", mpesaPhone:"", mpesaPayer:"",
        receipt: genReceipt(),
      }));
      setTimeout(() => setSaved(false), 4000);
    } catch (ex) {
      setErr("Failed to save. Check your connection and try again.");
      console.error(ex);
    } finally { setBusy(false); }
  };

  return (
    <div style={{ maxWidth:720 }}>
      <p style={{ fontWeight:600, fontSize:20, margin:"0 0 1.5rem", color:"#1F3864" }}>Revenue entry</p>

      {saved && (
        <div style={{ background:"#f0fdf4", border:"1px solid #86efac", borderRadius:10, padding:"12px 16px", marginBottom:18, fontSize:13, color:"#166534", display:"flex", alignItems:"center", gap:8 }}>
          <i className="ti ti-circle-check" style={{ fontSize:18 }} /> Record saved to database successfully.
        </div>
      )}
      {err && (
        <div style={{ background:"#fef2f2", border:"1px solid #fecaca", borderRadius:10, padding:"12px 16px", marginBottom:18, fontSize:13, color:"#dc2626" }}>{err}</div>
      )}

      <form onSubmit={submit} style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:14, padding:"1.75rem" }}>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16 }}>

          {/* Date */}
          <div>
            <label style={lbl}>Date *</label>
            <input type="date" style={inp} value={form.date} onChange={set("date")} required />
          </div>

          {/* Revenue stream */}
          <div>
            <label style={lbl}>Revenue stream *</label>
            <select style={inp} value={form.stream} onChange={set("stream")}>
              {STREAMS.map(s => <option key={s}>{s}</option>)}
            </select>
          </div>

          {/* Service */}
          <div>
            <label style={lbl}>Service *</label>
            <select style={inp} value={form.service} onChange={set("service")}>
              {SERVICES.map(s => <option key={s}>{s}</option>)}
            </select>
          </div>

          {/* Admission type */}
          <div>
            <label style={lbl}>Admission type</label>
            <select style={inp} value={form.admissionType} onChange={set("admissionType")}>
              {ADMISSION.map(a => <option key={a}>{a}</option>)}
            </select>
          </div>

          {/* Ward — inpatient only */}
          {form.admissionType === "Inpatient" && (
            <div>
              <label style={lbl}>Ward</label>
              <select style={inp} value={form.ward} onChange={set("ward")}>
                <option value="">Select ward…</option>
                {WARDS.map(w => <option key={w}>{w}</option>)}
              </select>
            </div>
          )}

          {/* Patient name */}
          <div>
            <label style={lbl}>Patient name</label>
            <input style={inp} value={form.patientName} onChange={set("patientName")} placeholder="Full name" />
          </div>

          {/* Patient / file no */}
          <div>
            <label style={lbl}>Patient / file no.</label>
            <input style={inp} value={form.patientNo} onChange={set("patientNo")} placeholder="LCRH-001234" />
          </div>

          {/* Description */}
          <div style={{ gridColumn:"1/-1" }}>
            <label style={lbl}>Description *</label>
            <input style={inp} value={form.description} onChange={set("description")}
              placeholder="e.g. Laboratory tests — malaria, CBC" required />
          </div>

          {/* Bill breakdown */}
          <div style={{ gridColumn:"1/-1", background:"#f8fafc", borderRadius:10, padding:"1rem", border:"1px solid #e5e7eb" }}>
            <p style={{ fontSize:12, fontWeight:600, color:"#1F3864", margin:"0 0 12px", textTransform:"uppercase", letterSpacing:"0.05em" }}>
              Bill breakdown
            </p>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:12 }}>
              <div>
                <label style={lbl}>Total bill (KES) *</label>
                <input type="number" min="0" step="0.01" style={inp}
                  value={form.totalBill} onChange={set("totalBill")} placeholder="0.00" required />
              </div>
              <div>
                <label style={lbl}>Amount paid (KES)</label>
                <input type="number" min="0" step="0.01" style={inp}
                  value={form.amountPaid} onChange={set("amountPaid")} placeholder="0.00" />
              </div>
              <div>
                <label style={lbl}>Amount waived (KES)</label>
                <input type="number" min="0" step="0.01" style={inp}
                  value={form.amountWaived} onChange={set("amountWaived")} placeholder="0.00" />
              </div>
              <div>
                <label style={lbl}>Balance (KES)</label>
                <div style={{
                  padding:"10px 12px", borderRadius:8, fontSize:14, fontWeight:700,
                  background: balance > 0 ? "#fef2f2" : balance < 0 ? "#fef9c3" : totalBill > 0 ? "#f0fdf4" : "#f9fafb",
                  color:      balance > 0 ? "#dc2626" : balance < 0 ? "#854d0e" : totalBill > 0 ? "#166534" : "#9ca3af",
                  border:     `1px solid ${balance > 0 ? "#fecaca" : balance < 0 ? "#fde68a" : totalBill > 0 ? "#86efac" : "#e5e7eb"}`
                }}>
                  {totalBill > 0 ? balance.toLocaleString("en-KE") : "—"}
                  {balance > 0 && <span style={{ fontSize:10, fontWeight:400, display:"block" }}>Outstanding</span>}
                  {balance === 0 && totalBill > 0 && <span style={{ fontSize:10, fontWeight:400, display:"block" }}>Fully paid</span>}
                  {balance < 0 && <span style={{ fontSize:10, fontWeight:400, display:"block" }}>Overpaid</span>}
                </div>
              </div>
            </div>
          </div>

          {/* Payment mode */}
          <div>
            <label style={lbl}>Payment mode</label>
            <select style={inp} value={form.paymentMode} onChange={set("paymentMode")}>
              {PAYMENT_MODES.map(m => <option key={m}>{m}</option>)}
            </select>
          </div>

          {/* Receipt number — always visible */}
          <div>
            <label style={lbl}>
              Receipt no. {isMpesa ? "(auto-filled from M-PESA code)" : "*"}
            </label>
            <input
              style={{ ...inp, background: isMpesa ? "#f9fafb" : "#fff", color: isMpesa ? "#6b7280" : "#111" }}
              value={isMpesa ? (form.mpesaCode.toUpperCase() || "Will use M-PESA code") : form.receipt}
              onChange={isMpesa ? undefined : set("receipt")}
              readOnly={isMpesa}
              placeholder={isMpesa ? "Auto-filled from M-PESA code below" : "RCP-000001"}
            />
          </div>

          {/* M-PESA fields — appear when M-PESA selected */}
          {isMpesa && (
            <div style={{ gridColumn:"1/-1", background:"#f0fdf4", border:"1px solid #86efac", borderRadius:10, padding:"1rem" }}>
              <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12 }}>
                <div style={{ width:32, height:32, borderRadius:8, background:"#16a34a", display:"flex", alignItems:"center", justifyContent:"center", fontSize:15, color:"#fff", fontWeight:700, flexShrink:0 }}>M</div>
                <p style={{ fontWeight:600, fontSize:13, margin:0, color:"#166534" }}>M-PESA payment details</p>
              </div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12 }}>
                <div>
                  <label style={{ ...lbl, color:"#166534" }}>M-PESA transaction code *</label>
                  <input
                    style={{ ...inp, fontFamily:"monospace", letterSpacing:"0.05em", textTransform:"uppercase", borderColor:"#86efac" }}
                    value={form.mpesaCode}
                    onChange={set("mpesaCode")}
                    placeholder="e.g. RGH4K2LMNP"
                  />
                </div>
                <div>
                  <label style={{ ...lbl, color:"#166534" }}>Payer name (on M-PESA)</label>
                  <input style={{ ...inp, borderColor:"#86efac" }} value={form.mpesaPayer} onChange={set("mpesaPayer")} placeholder="Name as shown on message" />
                </div>
                <div>
                  <label style={{ ...lbl, color:"#166534" }}>Phone number</label>
                  <input style={{ ...inp, borderColor:"#86efac" }} value={form.mpesaPhone} onChange={set("mpesaPhone")} placeholder="07XX XXX XXX" />
                </div>
              </div>
            </div>
          )}

          {/* Collector */}
          <div>
            <label style={lbl}>Collector / cashier</label>
            <input style={inp} value={form.collector} onChange={set("collector")} />
          </div>

          {/* Notes */}
          <div style={{ gridColumn:"1/-1" }}>
            <label style={lbl}>Notes (optional)</label>
            <textarea style={{ ...inp, resize:"vertical", minHeight:64, padding:"9px 12px", border:"1px solid #d1d5db", borderRadius:8, fontFamily:"Inter,sans-serif", fontSize:14 }}
              value={form.notes} onChange={set("notes")} placeholder="Any additional remarks…" />
          </div>
        </div>

        <div style={{ marginTop:20, display:"flex", gap:10 }}>
          <button type="submit" disabled={busy} style={{
            background: busy ? "#93a3c0" : "#1F3864", color:"#fff", border:"none",
            borderRadius:8, padding:"11px 28px", fontWeight:600, fontSize:14,
            cursor: busy ? "not-allowed" : "pointer"
          }}>
            {busy ? "Saving…" : "Save record"}
          </button>
          <button type="button" onClick={() => setForm(f => ({
            ...f, description:"", totalBill:"", amountPaid:"", amountWaived:"",
            patientName:"", patientNo:"", notes:"", mpesaCode:"", mpesaPhone:"", mpesaPayer:"", receipt: genReceipt()
          }))} style={{ background:"transparent", border:"1px solid #d1d5db", borderRadius:8, padding:"11px 20px", fontSize:14, color:"#6b7280", cursor:"pointer" }}>
            Clear
          </button>
        </div>
      </form>
    </div>
  );
}
