import React, { useEffect, useState } from "react";
import { db } from "../firebase/config";
import { collection, onSnapshot, query, orderBy } from "firebase/firestore";
import { useAuth } from "../firebase/AuthContext";
import {
  LineChart, Line, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend
} from "recharts";

const MONTHS   = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const SERVICES = [
  "Gas Refill","Waste Management","Dental","Wrong Parking","Laboratory",
  "Surgical","CT Scan","Renal","Pharmacy","Morgue","Card","ENT",
  "Orthopedic","Xray","Ultrasound","Special Clinic","Physiotherapy","Eye Unit","Attachment","Other"
];
const SERVICE_COLORS = [
  "#1F3864","#1D9E75","#C9A84C","#D85A30","#993556",
  "#534AB7","#5F5E5A","#0891b2","#16a34a","#dc2626",
  "#9333ea","#ea580c","#0284c7","#65a30d","#db2777",
  "#14b8a6","#f59e0b","#6366f1","#84cc16","#a8a29e"
];

const fmt      = n => "KES " + Number(n).toLocaleString("en-KE");
const fmtShort = n => {
  if (!n) return "KES 0";
  if (n >= 1e6) return `KES ${(n/1e6).toFixed(2)}M`;
  if (n >= 1e3) return `KES ${(n/1000).toFixed(1)}K`;
  return `KES ${n.toLocaleString("en-KE")}`;
};

function Spinner() {
  return (
    <div style={{ display:"flex", justifyContent:"center", alignItems:"center", height:300 }}>
      <div style={{ width:36, height:36, border:"3px solid #e5e7eb", borderTopColor:"#1F3864", borderRadius:"50%", animation:"spin 0.8s linear infinite" }} />
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

// ── KPI Card ───────────────────────────────────────────────────────────────
function KpiCard({ icon, iconBg, label, value, sub, subUp, subColor }) {
  return (
    <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1rem 1.25rem", display:"flex", alignItems:"center", gap:14 }}>
      <div style={{ width:48, height:48, borderRadius:12, background: iconBg||"#e0e7ff", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
        <i className={`ti ${icon}`} style={{ fontSize:24, color:"#fff" }} />
      </div>
      <div style={{ minWidth:0 }}>
        <p style={{ fontSize:11, fontWeight:500, color:"#6b7280", margin:"0 0 3px", textTransform:"uppercase", letterSpacing:"0.05em", whiteSpace:"nowrap" }}>{label}</p>
        <p style={{ fontSize:20, fontWeight:700, margin:"0 0 3px", color:"#1F3864", whiteSpace:"nowrap" }}>{value}</p>
        {sub && (
          <p style={{ fontSize:11, margin:0, color: subColor || "#9ca3af", display:"flex", alignItems:"center", gap:3 }}>
            {subUp !== undefined && <span style={{ color: subUp ? "#16a34a" : "#dc2626" }}>{subUp ? "▲" : "▼"}</span>}
            {sub}
          </p>
        )}
      </div>
    </div>
  );
}

// ── Gauge (collection status) ──────────────────────────────────────────────
function Gauge({ collected, total }) {
  const pct = total > 0 ? Math.min((collected / total) * 100, 100) : 0;
  const r = 80, cx = 100, cy = 100;
  const circumference = Math.PI * r; // half circle
  const offset = circumference * (1 - pct / 100);

  return (
    <div style={{ textAlign:"center" }}>
      <svg viewBox="0 0 200 110" width="200" height="110">
        {/* Background arc */}
        <path d={`M ${cx-r},${cy} A ${r},${r} 0 0,1 ${cx+r},${cy}`}
          fill="none" stroke="#f3f4f6" strokeWidth="18" strokeLinecap="round" />
        {/* Progress arc */}
        <path d={`M ${cx-r},${cy} A ${r},${r} 0 0,1 ${cx+r},${cy}`}
          fill="none" stroke="#1F3864" strokeWidth="18" strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          style={{ transition:"stroke-dashoffset 0.8s ease" }}
        />
        <text x={cx} y={cy-10} textAnchor="middle" fontSize="15" fontWeight="700" fill="#1F3864">{fmtShort(total)}</text>
        <text x={cx} y={cy+8}  textAnchor="middle" fontSize="10" fill="#6b7280">Total Assessed</text>
      </svg>
      <div style={{ display:"flex", justifyContent:"center", gap:24, marginTop:4 }}>
        <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:12 }}>
          <span style={{ width:10, height:10, borderRadius:"50%", background:"#1F3864", display:"inline-block" }} />
          <span style={{ color:"#374151" }}>Collected</span>
          <span style={{ fontWeight:600, color:"#1F3864" }}>{fmtShort(collected)} ({pct.toFixed(1)}%)</span>
        </div>
      </div>
      <div style={{ display:"flex", justifyContent:"center", gap:24, marginTop:4 }}>
        <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:12 }}>
          <span style={{ width:10, height:10, borderRadius:"50%", background:"#e5e7eb", display:"inline-block" }} />
          <span style={{ color:"#374151" }}>Outstanding</span>
          <span style={{ fontWeight:600, color:"#dc2626" }}>{fmtShort(total - collected)} ({(100-pct).toFixed(1)}%)</span>
        </div>
      </div>
    </div>
  );
}

// ── Main Dashboard ─────────────────────────────────────────────────────────
export default function Dashboard() {
  const { profile } = useAuth();
  const [revenue,   setRevenue]   = useState([]);
  const [insurance, setInsurance] = useState([]);
  const [loading,   setLoading]   = useState(true);
  const [period,    setPeriod]    = useState("monthly");

  useEffect(() => {
    let r = false, ins = false;
    const done = () => { if (r && ins) setLoading(false); };

    const q1 = query(collection(db,"revenue"), orderBy("date","desc"));
    const u1 = onSnapshot(q1, snap => {
      setRevenue(snap.docs.map(d=>({id:d.id,...d.data()})));
      r = true; done();
    });

    const q2 = query(collection(db,"insurance_claims"), orderBy("date","desc"));
    const u2 = onSnapshot(q2, snap => {
      setInsurance(snap.docs.map(d=>({id:d.id,...d.data()})));
      ins = true; done();
    });

    return () => { u1(); u2(); };
  }, []);

  if (loading) return <Spinner />;

  const now    = new Date();
  const curMo  = now.getMonth();
  const curYr  = now.getFullYear();
  const prevMo = curMo === 0 ? 11 : curMo - 1;
  const prevYr = curMo === 0 ? curYr - 1 : curYr;

  // ── Core metrics ──
  const totalBill    = revenue.reduce((s,r) => s + (r.totalBill    || 0), 0);
  const totalPaid    = revenue.reduce((s,r) => s + (r.amountPaid   || r.amount || 0), 0);
  const totalWaived  = revenue.reduce((s,r) => s + (r.amountWaived || 0), 0);
  const totalBalance = revenue.reduce((s,r) => s + (r.balance      || 0), 0);
  const insTotal     = insurance.reduce((s,c) => s + (c.claimAmount || 0), 0);

  // Current month
  const curRev  = revenue.filter(r => { const d=new Date(r.date); return d.getMonth()===curMo && d.getFullYear()===curYr; });
  const prevRev = revenue.filter(r => { const d=new Date(r.date); return d.getMonth()===prevMo && d.getFullYear()===prevYr; });
  const curMoPaid  = curRev.reduce((s,r)  => s + (r.amountPaid || r.amount || 0), 0);
  const prevMoPaid = prevRev.reduce((s,r) => s + (r.amountPaid || r.amount || 0), 0);
  const moGrowth   = prevMoPaid ? (((curMoPaid - prevMoPaid) / prevMoPaid) * 100) : null;

  // ── Monthly trend (last 12 months) ──
  const monthlyData = MONTHS.map((mo, i) => {
    const yr = i > curMo ? curYr - 1 : curYr;
    const recs = revenue.filter(r => { const d = new Date(r.date); return d.getMonth()===i && d.getFullYear()===yr; });
    const insRecs = insurance.filter(c => { const d = new Date(c.date); return d.getMonth()===i && d.getFullYear()===yr; });
    return {
      month: mo,
      Revenue:   recs.reduce((s,r) => s + (r.amountPaid || r.amount || 0), 0),
      Insurance: insRecs.reduce((s,c) => s + (c.claimAmount || 0), 0),
      Waived:    recs.reduce((s,r) => s + (r.amountWaived || 0), 0),
    };
  });

  // ── Revenue by service ──
  const byService = SERVICES.map((svc, i) => ({
    name:  svc,
    value: revenue.filter(r => r.service === svc).reduce((s,r) => s + (r.amountPaid || r.amount || 0), 0),
    color: SERVICE_COLORS[i],
  })).filter(s => s.value > 0).sort((a,b) => b.value - a.value).slice(0, 8);

  const svcTotal = byService.reduce((s,x) => s + x.value, 0);

  // ── Top waived by service ──
  const topWaived = SERVICES.map(svc => ({
    name:  svc,
    value: revenue.filter(r => r.service === svc).reduce((s,r) => s + (r.amountWaived || 0), 0),
  })).filter(s => s.value > 0).sort((a,b) => b.value - a.value).slice(0, 5);
  const waiveTotal = topWaived.reduce((s,x) => s + x.value, 0);

  // ── Payment channel breakdown ──
  const channels = ["Cash","M-PESA","Bank Transfer","Cheque","Insurance","Waiver","Other"].map(ch => ({
    name:  ch,
    value: revenue.filter(r => r.paymentMode === ch).reduce((s,r) => s + (r.amountPaid || r.amount || 0), 0),
  })).filter(c => c.value > 0).sort((a,b) => b.value - a.value);
  const chanTotal = channels.reduce((s,x) => s + x.value, 0);

  // ── Recent records ──
  const recent = revenue.slice(0, 6);

  // ── Admission breakdown ──
  const inpatient  = revenue.filter(r => r.admissionType === "Inpatient").length;
  const outpatient = revenue.filter(r => r.admissionType === "Outpatient").length;

  const STATUS_COLOR = { Pending:"#fef9c3", Posted:"#dcfce7", Verified:"#dbeafe" };
  const STATUS_TEXT  = { Pending:"#854d0e", Posted:"#166534", Verified:"#1e40af" };

  return (
    <div>
      {/* Header */}
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:"1.5rem", flexWrap:"wrap", gap:10 }}>
        <div>
          <p style={{ fontWeight:700, fontSize:22, margin:"0 0 2px", color:"#1F3864" }}>Dashboard</p>
          <p style={{ fontSize:13, color:"#6b7280", margin:0 }}>Overview of revenue collection performance — {MONTHS[curMo]} {curYr}</p>
        </div>
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:8, padding:"8px 14px", fontSize:13, color:"#374151", display:"flex", alignItems:"center", gap:6 }}>
            <i className="ti ti-calendar" style={{ fontSize:16, color:"#1F3864" }} />
            FY {curYr}/{String(curYr+1).slice(2)}
          </div>
          <div style={{ background:"#1F3864", borderRadius:8, padding:"8px 14px", fontSize:13, color:"#fff", display:"flex", alignItems:"center", gap:6 }}>
            <i className="ti ti-user-circle" style={{ fontSize:16 }} />
            {profile?.name || "User"} · <span style={{ opacity:0.7, textTransform:"capitalize" }}>{profile?.role}</span>
          </div>
        </div>
      </div>

      {/* ── KPI Row ── */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))", gap:12, marginBottom:"1.5rem" }}>
        <KpiCard icon="ti-wallet"       iconBg="#1F3864" label="Total Revenue (YTD)"       value={fmtShort(totalPaid)}   sub={`${revenue.length} records`} />
        <KpiCard icon="ti-trending-up"  iconBg="#1D9E75" label={`Revenue (${MONTHS[curMo]})`} value={fmtShort(curMoPaid)}
          sub={moGrowth !== null ? `${moGrowth > 0 ? "+" : ""}${moGrowth.toFixed(1)}% vs ${MONTHS[prevMo]}` : "No prior data"}
          subUp={moGrowth > 0} subColor={moGrowth > 0 ? "#16a34a" : "#dc2626"} />
        <KpiCard icon="ti-hand-off"     iconBg="#C9A84C" label="Waived Amount (YTD)"       value={fmtShort(totalWaived)} sub={`${revenue.filter(r=>r.amountWaived>0).length} waivers`} />
        <KpiCard icon="ti-shield-check" iconBg="#993556" label="Claimed per Insurance (YTD)" value={fmtShort(insTotal)}  sub={`${insurance.length} claims`} />
        <KpiCard icon="ti-alert-circle" iconBg="#D85A30" label="Outstanding (YTD)"          value={fmtShort(totalBalance)} sub={`${revenue.filter(r=>r.balance>0).length} unpaid`} subColor="#dc2626" />
      </div>

      {/* ── Row 2: Trend + Pie + Channels + System Overview ── */}
      <div style={{ display:"grid", gridTemplateColumns:"2fr 1.2fr 1fr 0.8fr", gap:14, marginBottom:14 }}>

        {/* Revenue trend */}
        <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
            <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:0, textTransform:"uppercase", letterSpacing:"0.05em" }}>Revenue Collection Trend</p>
          </div>
          {revenue.length === 0 ? (
            <div style={{ height:200, display:"flex", alignItems:"center", justifyContent:"center", color:"#d1d5db", flexDirection:"column", gap:8 }}>
              <i className="ti ti-chart-line" style={{ fontSize:40 }} />
              <span style={{ fontSize:13 }}>No data yet</span>
            </div>
          ) : (
            <ResponsiveContainer width="100%" height={200}>
              <LineChart data={monthlyData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
                <XAxis dataKey="month" tick={{ fontSize:10 }} />
                <YAxis tickFormatter={v => v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
                <Tooltip formatter={v => fmt(v)} />
                <Legend wrapperStyle={{ fontSize:11 }} />
                <Line type="monotone" dataKey="Revenue"   stroke="#1F3864" strokeWidth={2.5} dot={{ r:3 }} />
                <Line type="monotone" dataKey="Insurance" stroke="#993556" strokeWidth={2} dot={{ r:2 }} strokeDasharray="4 2" />
              </LineChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Revenue by service pie */}
        <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem" }}>
          <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:"0 0 0.75rem", textTransform:"uppercase", letterSpacing:"0.05em" }}>Revenue by Service (YTD)</p>
          {byService.length === 0 ? (
            <div style={{ height:160, display:"flex", alignItems:"center", justifyContent:"center", color:"#d1d5db" }}>No data</div>
          ) : (
            <>
              <ResponsiveContainer width="100%" height={150}>
                <PieChart>
                  <Pie data={byService} cx="50%" cy="50%" innerRadius={40} outerRadius={65} dataKey="value" nameKey="name">
                    {byService.map((e,i) => <Cell key={i} fill={e.color} />)}
                  </Pie>
                  <Tooltip formatter={v => fmt(v)} />
                </PieChart>
              </ResponsiveContainer>
              <div style={{ marginTop:8 }}>
                {byService.slice(0,5).map(s => (
                  <div key={s.name} style={{ display:"flex", justifyContent:"space-between", fontSize:11, marginBottom:4, alignItems:"center" }}>
                    <span style={{ display:"flex", alignItems:"center", gap:5 }}>
                      <span style={{ width:7, height:7, borderRadius:2, background:s.color, display:"inline-block", flexShrink:0 }} />
                      {s.name}
                    </span>
                    <span style={{ color:"#6b7280" }}>{svcTotal ? ((s.value/svcTotal)*100).toFixed(0) : 0}%</span>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>

        {/* Collection channels */}
        <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem" }}>
          <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:"0 0 0.75rem", textTransform:"uppercase", letterSpacing:"0.05em" }}>Collection Channels (YTD)</p>
          {channels.length === 0 ? (
            <div style={{ color:"#d1d5db", fontSize:13, textAlign:"center", paddingTop:"2rem" }}>No data</div>
          ) : (
            channels.map((ch, i) => {
              const icons = { Cash:"ti-cash", "M-PESA":"ti-brand-android", "Bank Transfer":"ti-building-bank", Cheque:"ti-file-invoice", Insurance:"ti-shield-check", Waiver:"ti-hand-off", Other:"ti-dots" };
              const colors = ["#1F3864","#16a34a","#0891b2","#9333ea","#993556","#C9A84C","#6b7280"];
              return (
                <div key={ch.name} style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10 }}>
                  <i className={`ti ${icons[ch.name]||"ti-dots"}`} style={{ fontSize:16, color:colors[i]||"#6b7280", flexShrink:0 }} />
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, marginBottom:3 }}>
                      <span style={{ color:"#374151", fontWeight:500 }}>{ch.name}</span>
                      <span style={{ color:"#6b7280" }}>{chanTotal ? ((ch.value/chanTotal)*100).toFixed(1) : 0}%</span>
                    </div>
                    <div style={{ height:4, background:"#f3f4f6", borderRadius:2 }}>
                      <div style={{ height:4, borderRadius:2, background:colors[i]||"#6b7280", width:`${chanTotal?((ch.value/chanTotal)*100):0}%` }} />
                    </div>
                  </div>
                  <span style={{ fontSize:11, color:"#6b7280", whiteSpace:"nowrap" }}>{fmtShort(ch.value)}</span>
                </div>
              );
            })
          )}
        </div>

        {/* System overview */}
        <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem" }}>
          <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:"0 0 0.75rem", textTransform:"uppercase", letterSpacing:"0.05em" }}>System Overview</p>
          {[
            { label:"Total Billed (YTD)", value:fmtShort(totalBill), icon:"ti-file-invoice", color:"#1F3864", bg:"#e0e7ff" },
            { label:"Collected (YTD)",    value:fmtShort(totalPaid),  icon:"ti-coins",        color:"#16a34a", bg:"#dcfce7" },
            { label:"Outstanding (YTD)", value:fmtShort(totalBalance),icon:"ti-alert-circle", color:"#dc2626", bg:"#fee2e2" },
            { label:"Insurance Claims",  value:fmtShort(insTotal),   icon:"ti-shield-check", color:"#993556", bg:"#fce7f3" },
          ].map(item => (
            <div key={item.label} style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12 }}>
              <div style={{ width:32, height:32, borderRadius:8, background:item.bg, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
                <i className={`ti ${item.icon}`} style={{ fontSize:16, color:item.color }} />
              </div>
              <div>
                <p style={{ fontSize:10, color:"#9ca3af", margin:"0 0 1px" }}>{item.label}</p>
                <p style={{ fontSize:13, fontWeight:700, color:item.color, margin:0 }}>{item.value}</p>
              </div>
            </div>
          ))}
          {/* Admission split */}
          <div style={{ marginTop:8, paddingTop:8, borderTop:"1px solid #f3f4f6" }}>
            <p style={{ fontSize:10, color:"#9ca3af", margin:"0 0 6px" }}>ADMISSIONS</p>
            <div style={{ display:"flex", gap:8 }}>
              <div style={{ flex:1, background:"#f0f4f9", borderRadius:6, padding:"6px 8px", textAlign:"center" }}>
                <p style={{ fontSize:11, fontWeight:600, color:"#1F3864", margin:0 }}>{inpatient}</p>
                <p style={{ fontSize:10, color:"#6b7280", margin:0 }}>Inpatient</p>
              </div>
              <div style={{ flex:1, background:"#f0fdf4", borderRadius:6, padding:"6px 8px", textAlign:"center" }}>
                <p style={{ fontSize:11, fontWeight:600, color:"#16a34a", margin:0 }}>{outpatient}</p>
                <p style={{ fontSize:10, color:"#6b7280", margin:0 }}>Outpatient</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ── Row 3: Gauge + Waived + Bar chart ── */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 2fr", gap:14, marginBottom:14 }}>

        {/* Collection status gauge */}
        <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem" }}>
          <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:"0 0 1rem", textTransform:"uppercase", letterSpacing:"0.05em" }}>Collection Status (YTD)</p>
          <Gauge collected={totalPaid} total={totalBill || totalPaid} />
        </div>

        {/* Top waived per service */}
        <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem" }}>
          <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:"0 0 1rem", textTransform:"uppercase", letterSpacing:"0.05em" }}>Top Waived Revenue per Service</p>
          {topWaived.length === 0 ? (
            <div style={{ color:"#d1d5db", fontSize:13, textAlign:"center", paddingTop:"2rem" }}>No waivers recorded</div>
          ) : (
            topWaived.map((item, i) => {
              const colors = ["#1F3864","#1D9E75","#C9A84C","#993556","#D85A30"];
              return (
                <div key={item.name} style={{ marginBottom:12 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginBottom:4 }}>
                    <span style={{ color:"#374151", fontWeight:500 }}>{item.name}</span>
                    <span style={{ color:"#6b7280" }}>{fmtShort(item.value)} ({waiveTotal?((item.value/waiveTotal)*100).toFixed(0):0}%)</span>
                  </div>
                  <div style={{ height:6, background:"#f3f4f6", borderRadius:3 }}>
                    <div style={{ height:6, borderRadius:3, background:colors[i]||"#6b7280", width:`${waiveTotal?((item.value/waiveTotal)*100):0}%` }} />
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Service bar chart */}
        <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem" }}>
          <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:"0 0 1rem", textTransform:"uppercase", letterSpacing:"0.05em" }}>Revenue by Service — Monthly</p>
          {revenue.length === 0 ? (
            <div style={{ height:180, display:"flex", alignItems:"center", justifyContent:"center", color:"#d1d5db", flexDirection:"column", gap:8 }}>
              <i className="ti ti-chart-bar" style={{ fontSize:40 }} /><span style={{ fontSize:13 }}>No data yet</span>
            </div>
          ) : (
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={monthlyData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
                <XAxis dataKey="month" tick={{ fontSize:10 }} />
                <YAxis tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
                <Tooltip formatter={v=>fmt(v)} />
                <Bar dataKey="Revenue" fill="#1F3864" radius={[4,4,0,0]} />
                <Bar dataKey="Waived"  fill="#C9A84C" radius={[4,4,0,0]} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>

      {/* ── Recent Collections ── */}
      <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, overflow:"hidden" }}>
        <div style={{ padding:"1rem 1.5rem", borderBottom:"1px solid #f3f4f6", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
          <p style={{ fontSize:12, fontWeight:600, color:"#374151", margin:0, textTransform:"uppercase", letterSpacing:"0.05em" }}>Recent Collections</p>
          <span style={{ fontSize:12, color:"#9ca3af" }}>Latest {recent.length} entries</span>
        </div>
        {recent.length === 0 ? (
          <div style={{ padding:"3rem", textAlign:"center", color:"#9ca3af" }}>
            <i className="ti ti-table-off" style={{ fontSize:40, display:"block", marginBottom:8 }} />
            No records yet. Use Revenue Entry to add the first record.
          </div>
        ) : (
          <div style={{ overflowX:"auto" }}>
            <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
              <thead>
                <tr style={{ background:"#f9fafb" }}>
                  {["Receipt No.","Date","Patient","Service","Admission","Total Bill","Paid","Waived","Balance","Mode","Status"].map(h=>(
                    <th key={h} style={{ padding:"9px 14px", textAlign:"left", fontWeight:500, color:"#6b7280", fontSize:11, borderBottom:"1px solid #e5e7eb", whiteSpace:"nowrap" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {recent.map((r,i) => {
                  const bg  = STATUS_COLOR[r.status] || "#f9fafb";
                  const col = STATUS_TEXT[r.status]  || "#6b7280";
                  const bal = r.balance ?? ((r.totalBill||0) - (r.amountPaid||r.amount||0) - (r.amountWaived||0));
                  return (
                    <tr key={r.id} style={{ borderBottom:"1px solid #f9fafb", background:i%2?"#fafafa":"#fff" }}>
                      <td style={{ padding:"9px 14px", fontFamily:"monospace", fontSize:11, color:"#1F3864", fontWeight:600 }}>{r.receipt||"—"}</td>
                      <td style={{ padding:"9px 14px", whiteSpace:"nowrap", color:"#6b7280" }}>{r.date}</td>
                      <td style={{ padding:"9px 14px", fontWeight:500 }}>{r.patientName||"—"}</td>
                      <td style={{ padding:"9px 14px", color:"#6b7280" }}>{r.service||r.stream||"—"}</td>
                      <td style={{ padding:"9px 14px", color:"#6b7280" }}>{r.admissionType||"—"}</td>
                      <td style={{ padding:"9px 14px", fontWeight:500 }}>{r.totalBill ? r.totalBill.toLocaleString("en-KE") : "—"}</td>
                      <td style={{ padding:"9px 14px", color:"#166534", fontWeight:500 }}>{(r.amountPaid||r.amount||0).toLocaleString("en-KE")}</td>
                      <td style={{ padding:"9px 14px", color:"#854d0e" }}>{r.amountWaived ? r.amountWaived.toLocaleString("en-KE") : "—"}</td>
                      <td style={{ padding:"9px 14px", color: bal>0?"#dc2626":bal===0?"#166534":"#854d0e", fontWeight:500 }}>
                        {bal !== undefined ? bal.toLocaleString("en-KE") : "—"}
                      </td>
                      <td style={{ padding:"9px 14px", color:"#6b7280" }}>{r.paymentMode||"—"}</td>
                      <td style={{ padding:"9px 14px" }}>
                        <span style={{ background:bg, color:col, borderRadius:20, padding:"2px 10px", fontSize:11, fontWeight:500 }}>{r.status||"Pending"}</span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
