// Central role/permission definitions for LCRH Revenue System

export const ROLES = ["superuser", "admin", "finance", "viewer"];

export const ROLE_DESC = {
  superuser: "Maximum access — delete/override records, system config, audit logs, archive/restore, CSV export",
  admin:     "Full access — manage users, verify records, all reports",
  finance:   "Enter revenue & claims, view all records and reports",
  viewer:    "View records and reports only — cannot enter data",
};

export const ROLE_BADGE = {
  superuser: { bg: "#fdf4ff", color: "#6b21a8" },
  admin:     { bg: "#fee2e2", color: "#991b1b" },
  finance:   { bg: "#dbeafe", color: "#1e40af" },
  viewer:    { bg: "#f3f4f6", color: "#374151" },
};

/**
 * Check whether a role has permission to perform an action.
 * @param {string} role
 * @param {string} action
 * @returns {boolean}
 */
export const can = (role, action) => {
  const su  = role === "superuser";
  const adm = su || role === "admin";
  const fin = adm || role === "finance";

  const map = {
    // General access
    viewDashboard:      true,
    viewRecords:        true,
    viewAnalytics:      true,
    viewReports:        true,
    viewInsurance:      true,
    viewSettings:       true,

    // Finance actions
    enterRevenue:       fin,

    // Admin actions
    manageUsers:        adm,
    changeRecordStatus: adm,
    deleteRecord:       adm,

    // SuperUser-only actions
    overridePosted:     su,
    bulkExport:         su,
    systemConfig:       su,
    viewAuditLog:       su,
    archiveRestore:     su,
    downloadReports:    su,   // Word / PDF report downloads
  };

  return map[action] ?? false;
};
