import React, { useEffect, useState, useMemo } from "react";
import { db } from "../firebase/config";
import {
  collection, onSnapshot, query, orderBy, limit,
  doc, getDoc, setDoc, updateDoc, getDocs, where
} from "firebase/firestore";
import { useAuth } from "../firebase/AuthContext";
import { logAction } from "../utils/audit";
import { CONFIG_DEFAULTS } from "../hooks/useConfig";

// ─── helpers ────────────────────────────────────────────────────────────────
const fmt  = n  => "KES " + Number(n || 0).toLocaleString("en-KE");
const fmtTs = ts => {
  if (!ts) return "—";
  const d = ts.toDate ? ts.toDate() : new Date(ts);
  return d.toLocaleString("en-KE", { dateStyle: "short", timeStyle: "short" });
};

const TAB_STYLE = (active) => ({
  padding: "9px 18px", border: "none", borderRadius: 8, cursor: "pointer",
  fontWeight: active ? 600 : 400, fontSize: 13,
  background: active ? "#1F3864" : "transparent",
  color:      active ? "#C9A84C" : "#6b7280",
  transition: "all 0.15s",
});

// ─── Main Component ──────────────────────────────────────────────────────────
export default function SystemAdmin() {
  const [tab, setTab] = useState("config");

  const tabs = [
    { id: "config",  label: "⚙️  System Config" },
    { id: "audit",   label: "📋  Audit Log" },
    { id: "archive", label: "🗄️  Archive" },
    { id: "export",  label: "📥  CSV Export" },
  ];

  return (
    <div>
      <p style={{ fontWeight: 600, fontSize: 20, margin: "0 0 4px", color: "#1F3864" }}>System Admin</p>
      <p style={{ fontSize: 12, color: "#9ca3af", margin: "0 0 1.25rem" }}>
        Super-user only — system configuration, audit trail, archive management &amp; bulk export.
      </p>

      {/* Tab bar */}
      <div style={{ display: "flex", gap: 4, marginBottom: 20, flexWrap: "wrap",
        background: "#f3f4f6", borderRadius: 10, padding: 4 }}>
        {tabs.map(t => (
          <button key={t.id} onClick={() => setTab(t.id)} style={TAB_STYLE(tab === t.id)}>
            {t.label}
          </button>
        ))}
      </div>

      {tab === "config"  && <ConfigTab />}
      {tab === "audit"   && <AuditTab />}
      {tab === "archive" && <ArchiveTab />}
      {tab === "export"  && <ExportTab />}
    </div>
  );
}

// ─── System Config Tab ───────────────────────────────────────────────────────
function ConfigTab() {
  const { user, profile } = useAuth();
  const actor = { uid: user?.uid, name: profile?.name, role: profile?.role };

  const [cfg, setCfg]     = useState(null);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg]      = useState("");
  const [newItem, setNewItem] = useState({ services: "", wards: "", insurance: "", streams: "" });

  useEffect(() => {
    getDoc(doc(db, "config", "app_config")).then(snap => {
      setCfg(snap.exists() ? { ...CONFIG_DEFAULTS, ...snap.data() } : { ...CONFIG_DEFAULTS });
    });
  }, []);

  const save = async (field, list) => {
    setSaving(true);
    try {
      await setDoc(doc(db, "config", "app_config"), { [field]: list }, { merge: true });
      await logAction(actor, "SYSTEM_CONFIG_UPDATED", { field, count: list.length });
      setMsg(`✓ ${field} saved.`);
      setTimeout(() => setMsg(""), 3000);
    } catch (e) {
      setMsg("Error saving: " + e.message);
    } finally { setSaving(false); }
  };

  const addItem = (field) => {
    const val = newItem[field]?.trim();
    if (!val) return;
    if (cfg[field].includes(val)) { setMsg("Item already exists."); setTimeout(() => setMsg(""), 2000); return; }
    const updated = [...cfg[field], val];
    setCfg(c => ({ ...c, [field]: updated }));
    setNewItem(n => ({ ...n, [field]: "" }));
    save(field, updated);
  };

  const removeItem = (field, item) => {
    if (!window.confirm(`Remove "${item}" from ${field}?`)) return;
    const updated = cfg[field].filter(i => i !== item);
    setCfg(c => ({ ...c, [field]: updated }));
    save(field, updated);
  };

  if (!cfg) return <Spinner />;

  const sections = [
    { key: "services",  label: "Services",          color: "#1F3864" },
    { key: "wards",     label: "Wards",              color: "#1D9E75" },
    { key: "insurance", label: "Insurance Schemes",  color: "#993556" },
    { key: "streams",   label: "Revenue Streams",    color: "#C9A84C" },
  ];

  return (
    <div>
      {msg && (
        <div style={{ background: msg.startsWith("✓") ? "#f0fdf4" : "#fef2f2",
          border: `1px solid ${msg.startsWith("✓") ? "#86efac" : "#fecaca"}`,
          color: msg.startsWith("✓") ? "#166534" : "#dc2626",
          borderRadius: 8, padding: "10px 14px", fontSize: 13, marginBottom: 16 }}>{msg}</div>
      )}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 16 }}>
        {sections.map(({ key, label, color }) => (
          <div key={key} style={{ background: "#fff", border: "1px solid #e5e7eb", borderRadius: 12, overflow: "hidden" }}>
            <div style={{ background: color, padding: "10px 14px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ fontWeight: 600, color: "#fff", fontSize: 13 }}>{label}</span>
              <span style={{ background: "rgba(255,255,255,0.2)", color: "#fff", borderRadius: 20, padding: "2px 8px", fontSize: 11 }}>{cfg[key].length} items</span>
            </div>
            <div style={{ padding: 12 }}>
              <div style={{ maxHeight: 200, overflowY: "auto", marginBottom: 10 }}>
                {cfg[key].map(item => (
                  <div key={item} style={{ display: "flex", justifyContent: "space-between", alignItems: "center",
                    padding: "5px 8px", borderRadius: 6, marginBottom: 3,
                    background: "#f9fafb", fontSize: 13 }}>
                    <span>{item}</span>
                    <button onClick={() => removeItem(key, item)} disabled={saving}
                      style={{ background: "none", border: "none", color: "#dc2626", cursor: "pointer", fontSize: 14, padding: 0 }}>×</button>
                  </div>
                ))}
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                <input
                  value={newItem[key]}
                  onChange={e => setNewItem(n => ({ ...n, [key]: e.target.value }))}
                  onKeyDown={e => e.key === "Enter" && addItem(key)}
                  placeholder={`Add ${label.slice(0, -1).toLowerCase()}…`}
                  style={{ flex: 1, fontSize: 12, padding: "6px 10px" }}
                />
                <button onClick={() => addItem(key)} disabled={saving}
                  style={{ background: color, color: "#fff", border: "none", borderRadius: 6,
                    padding: "6px 12px", fontSize: 12, cursor: "pointer", fontWeight: 600 }}>+</button>
              </div>
            </div>
          </div>
        ))}
      </div>
      <p style={{ fontSize: 11, color: "#9ca3af", marginTop: 14 }}>
        Changes take effect immediately across Revenue Entry, Insurance, and Reports modules.
      </p>
    </div>
  );
}

// ─── Audit Log Tab ───────────────────────────────────────────────────────────
function AuditTab() {
  const [logs, setLogs]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter]   = useState("");

  useEffect(() => {
    const q = query(collection(db, "audit_logs"), orderBy("ts", "desc"), limit(200));
    const unsub = onSnapshot(q, snap => {
      setLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setLoading(false);
    });
    return unsub;
  }, []);

  const filtered = useMemo(() => {
    if (!filter) return logs;
    const q = filter.toLowerCase();
    return logs.filter(l =>
      l.action?.toLowerCase().includes(q) ||
      l.userName?.toLowerCase().includes(q) ||
      l.userRole?.toLowerCase().includes(q) ||
      JSON.stringify(l.details || {}).toLowerCase().includes(q)
    );
  }, [logs, filter]);

  const ACTION_COLOR = {
    DELETE:    { bg: "#fef2f2", color: "#dc2626" },
    CREATE:    { bg: "#f0fdf4", color: "#16a34a" },
    UPDATE:    { bg: "#eff6ff", color: "#2563eb" },
    ARCHIVE:   { bg: "#fefce8", color: "#ca8a04" },
    RESTORE:   { bg: "#f0fdf4", color: "#059669" },
    OVERRIDE:  { bg: "#fdf4ff", color: "#7c3aed" },
    CONFIG:    { bg: "#f0f9ff", color: "#0369a1" },
  };

  const badge = (action = "") => {
    const key = Object.keys(ACTION_COLOR).find(k => action.includes(k)) || "UPDATE";
    const s = ACTION_COLOR[key];
    return (
      <span style={{ background: s.bg, color: s.color, borderRadius: 20,
        padding: "2px 9px", fontSize: 11, fontWeight: 600, whiteSpace: "nowrap" }}>
        {action}
      </span>
    );
  };

  if (loading) return <Spinner />;

  return (
    <div>
      <div style={{ display: "flex", gap: 10, marginBottom: 14, alignItems: "center" }}>
        <input value={filter} onChange={e => setFilter(e.target.value)}
          placeholder="Search action, user, details…"
          style={{ flex: 1, maxWidth: 400 }} />
        <span style={{ fontSize: 12, color: "#9ca3af" }}>{filtered.length} of {logs.length} entries (latest 200)</span>
      </div>

      {filtered.length === 0 ? (
        <div style={{ textAlign: "center", padding: "3rem", background: "#fff", borderRadius: 12, border: "1px solid #e5e7eb" }}>
          <p style={{ color: "#9ca3af", fontSize: 14 }}>No audit log entries yet. Actions will appear here as users interact with the system.</p>
        </div>
      ) : (
        <div style={{ overflowX: "auto", borderRadius: 12, border: "1px solid #e5e7eb" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
            <thead>
              <tr style={{ background: "#f9fafb" }}>
                {["Timestamp","User","Role","Action","Details"].map(h => (
                  <th key={h} style={{ padding: "10px 12px", textAlign: "left", fontWeight: 500, color: "#6b7280", fontSize: 11, borderBottom: "1px solid #e5e7eb", whiteSpace: "nowrap" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((l, i) => (
                <tr key={l.id} style={{ borderBottom: "1px solid #f3f4f6", background: i % 2 ? "#fafafa" : "#fff" }}>
                  <td style={{ padding: "8px 12px", whiteSpace: "nowrap", fontSize: 11, color: "#6b7280" }}>{fmtTs(l.ts)}</td>
                  <td style={{ padding: "8px 12px", fontWeight: 500 }}>{l.userName}</td>
                  <td style={{ padding: "8px 12px", textTransform: "capitalize", color: "#6b7280", fontSize: 12 }}>{l.userRole}</td>
                  <td style={{ padding: "8px 12px" }}>{badge(l.action)}</td>
                  <td style={{ padding: "8px 12px", fontSize: 11, color: "#6b7280", maxWidth: 300, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {JSON.stringify(l.details || {})}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// ─── Archive Tab ─────────────────────────────────────────────────────────────
function ArchiveTab() {
  const { user, profile } = useAuth();
  const actor = { uid: user?.uid, name: profile?.name, role: profile?.role };

  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy]       = useState(null);

  useEffect(() => {
    const q = query(collection(db, "revenue"), where("archived", "==", true), orderBy("date", "desc"));
    const unsub = onSnapshot(q, snap => {
      setRecords(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setLoading(false);
    });
    return unsub;
  }, []);

  const restore = async (r) => {
    if (!window.confirm(`Restore record ${r.receipt}? It will reappear in Records.`)) return;
    setBusy(r.id);
    try {
      await updateDoc(doc(db, "revenue", r.id), { archived: false });
      await logAction(actor, "RECORD_RESTORED", { receipt: r.receipt, amount: r.amount });
    } finally { setBusy(null); }
  };

  if (loading) return <Spinner />;

  return (
    <div>
      <div style={{ background: "#fffbeb", border: "1px solid #fde68a", borderRadius: 8, padding: "10px 14px", fontSize: 12, color: "#92400e", marginBottom: 16 }}>
        Archived records are hidden from normal Records view. Restore them to make them visible again.
        {records.length > 0 && ` ${records.length} archived record${records.length > 1 ? "s" : ""} found.`}
      </div>

      {records.length === 0 ? (
        <div style={{ textAlign: "center", padding: "3rem", background: "#fff", borderRadius: 12, border: "1px solid #e5e7eb" }}>
          <i className="ti ti-archive-off" style={{ fontSize: 40, color: "#d1d5db", display: "block", marginBottom: 10 }} />
          <p style={{ color: "#9ca3af" }}>No archived records.</p>
        </div>
      ) : (
        <div style={{ overflowX: "auto", borderRadius: 12, border: "1px solid #e5e7eb" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
            <thead>
              <tr style={{ background: "#f9fafb" }}>
                {["Date","Receipt","Stream","Description","Amount","Collector",""].map((h, i) => (
                  <th key={i} style={{ padding: "10px 12px", textAlign: "left", fontWeight: 500, color: "#6b7280", fontSize: 11, borderBottom: "1px solid #e5e7eb" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {records.map((r, i) => (
                <tr key={r.id} style={{ borderBottom: "1px solid #f3f4f6", background: i % 2 ? "#fafafa" : "#fff" }}>
                  <td style={{ padding: "9px 12px", whiteSpace: "nowrap" }}>{r.date}</td>
                  <td style={{ padding: "9px 12px", fontFamily: "monospace", fontSize: 11, color: "#6b7280" }}>{r.receipt}</td>
                  <td style={{ padding: "9px 12px" }}>{r.stream}</td>
                  <td style={{ padding: "9px 12px", maxWidth: 160, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.description}</td>
                  <td style={{ padding: "9px 12px", fontWeight: 600, color: "#1F3864" }}>{fmt(r.amount)}</td>
                  <td style={{ padding: "9px 12px" }}>{r.collector}</td>
                  <td style={{ padding: "9px 12px" }}>
                    <button onClick={() => restore(r)} disabled={busy === r.id}
                      style={{ background: "#1D9E75", color: "#fff", border: "none", borderRadius: 6,
                        padding: "5px 12px", fontSize: 12, cursor: "pointer", fontWeight: 500 }}>
                      {busy === r.id ? "…" : "Restore"}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// ─── CSV Export Tab ───────────────────────────────────────────────────────────
function ExportTab() {
  const { user, profile } = useAuth();
  const actor = { uid: user?.uid, name: profile?.name, role: profile?.role };

  const [dateFrom, setDateFrom] = useState(() => {
    const d = new Date(); d.setMonth(d.getMonth() - 1);
    return d.toISOString().slice(0, 10);
  });
  const [dateTo,   setDateTo]   = useState(() => new Date().toISOString().slice(0, 10));
  const [stream,   setStream]   = useState("All");
  const [status,   setStatus]   = useState("All");
  const [loading,  setLoading]  = useState(false);
  const [count,    setCount]    = useState(null);
  const [msg,      setMsg]      = useState("");

  const STREAMS = ["OPD Fees","IPD Charges","Lab Services","Pharmacy","Maternity","Radiology","Other"];

  const exportCSV = async () => {
    setLoading(true); setMsg(""); setCount(null);
    try {
      // Fetch all non-archived revenue records
      const snap = await getDocs(collection(db, "revenue"));
      let rows = snap.docs.map(d => ({ id: d.id, ...d.data() }))
        .filter(r => !r.archived)
        .filter(r => r.date >= dateFrom && r.date <= dateTo)
        .filter(r => stream === "All" || r.stream === stream)
        .filter(r => status === "All" || r.status === status)
        .sort((a, b) => a.date.localeCompare(b.date));

      setCount(rows.length);
      if (rows.length === 0) { setMsg("No records match the selected filters."); setLoading(false); return; }

      const headers = [
        "Date","Receipt","Stream","Service","AdmissionType","Ward",
        "PatientName","PatientNo","Description",
        "TotalBill","AmountPaid","AmountWaived","Balance",
        "PaymentMode","MPESACode","MPESAPhone","MPESAPayer",
        "Collector","Status","Notes","CreatedAt"
      ];

      const escape = v => {
        if (v == null) return "";
        const s = String(v).replace(/"/g, '""');
        return /[",\n\r]/.test(s) ? `"${s}"` : s;
      };

      const csvRows = [
        headers.join(","),
        ...rows.map(r => [
          r.date, r.receipt, r.stream, r.service, r.admissionType, r.ward || "",
          r.patientName || "", r.patientNo || "", r.description || "",
          r.totalBill || r.amount || 0, r.amountPaid || 0, r.amountWaived || 0,
          (r.totalBill || r.amount || 0) - (r.amountPaid || 0) - (r.amountWaived || 0),
          r.paymentMode || "", r.mpesaCode || "", r.mpesaPhone || "", r.mpesaPayer || "",
          r.collector || "", r.status || "", r.notes || "",
          r.createdAt?.toDate ? r.createdAt.toDate().toISOString() : (r.createdAt || "")
        ].map(escape).join(","))
      ];

      const blob = new Blob([csvRows.join("\r\n")], { type: "text/csv;charset=utf-8;" });
      const url  = URL.createObjectURL(blob);
      const a    = document.createElement("a");
      a.href     = url;
      a.download = `LCRH_Revenue_${dateFrom}_to_${dateTo}.csv`;
      a.click();
      URL.revokeObjectURL(url);

      await logAction(actor, "BULK_CSV_EXPORT", { dateFrom, dateTo, stream, status, count: rows.length });
      setMsg(`✓ Exported ${rows.length} records.`);
    } catch (e) {
      setMsg("Export failed: " + e.message);
    } finally { setLoading(false); }
  };

  return (
    <div>
      <div style={{ background: "#fff", border: "1px solid #e5e7eb", borderRadius: 12, padding: "1.5rem", maxWidth: 540 }}>
        <p style={{ fontWeight: 600, fontSize: 15, color: "#1F3864", margin: "0 0 1rem" }}>Export Records to CSV</p>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
          <div>
            <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>From date</label>
            <input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} style={{ width: "100%", boxSizing: "border-box" }} />
          </div>
          <div>
            <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>To date</label>
            <input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} style={{ width: "100%", boxSizing: "border-box" }} />
          </div>
          <div>
            <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>Stream</label>
            <select value={stream} onChange={e => setStream(e.target.value)} style={{ width: "100%", boxSizing: "border-box" }}>
              <option>All</option>{STREAMS.map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>Status</label>
            <select value={status} onChange={e => setStatus(e.target.value)} style={{ width: "100%", boxSizing: "border-box" }}>
              {["All","Pending","Posted","Verified"].map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
        </div>

        <button onClick={exportCSV} disabled={loading}
          style={{ background: loading ? "#93a3c0" : "#1F3864", color: "#fff",
            border: "none", borderRadius: 8, padding: "11px 24px",
            fontWeight: 600, fontSize: 14, cursor: loading ? "not-allowed" : "pointer",
            display: "flex", alignItems: "center", gap: 8 }}>
          <i className="ti ti-download" style={{ fontSize: 16 }} />
          {loading ? "Exporting…" : "Export CSV"}
        </button>

        {msg && (
          <div style={{ marginTop: 12, padding: "10px 14px", borderRadius: 8, fontSize: 13,
            background: msg.startsWith("✓") ? "#f0fdf4" : "#fef2f2",
            color: msg.startsWith("✓") ? "#166534" : "#dc2626",
            border: `1px solid ${msg.startsWith("✓") ? "#86efac" : "#fecaca"}` }}>
            {msg}
          </div>
        )}
      </div>

      <div style={{ marginTop: 14, background: "#f0f9ff", border: "1px solid #bae6fd", borderRadius: 8, padding: "10px 14px", fontSize: 12, color: "#0369a1" }}>
        <strong>Exported fields:</strong> Date, Receipt, Stream, Service, Admission Type, Ward, Patient Name/No, Description, Total Bill, Amount Paid, Waived, Balance, Payment Mode, M-PESA details, Collector, Status, Notes, Created At.
        Archived records are excluded from exports.
      </div>
    </div>
  );
}

// ─── Shared ──────────────────────────────────────────────────────────────────
function Spinner() {
  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "3rem" }}>
      <div style={{ width: 32, height: 32, border: "3px solid #e5e7eb", borderTopColor: "#1F3864", borderRadius: "50%", animation: "spin 0.8s linear infinite" }} />
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}
