import React, { useEffect, useState, useMemo } from "react";
import { db } from "../firebase/config";
import {
  collection, onSnapshot, query, orderBy,
  doc, updateDoc, deleteDoc
} from "firebase/firestore";
import { useAuth } from "../firebase/AuthContext";
import { can } from "../utils/permissions";
import { logAction } from "../utils/audit";
import { exportRecordsPDF, exportRecordsDocx } from "../utils/reportExport";

const STREAMS = ["OPD Fees","IPD Charges","Lab Services","Pharmacy","Maternity","Radiology","Other"];
const STREAM_COLORS = {
  "OPD Fees":"#1F3864","IPD Charges":"#1D9E75","Lab Services":"#C9A84C",
  "Pharmacy":"#D85A30","Maternity":"#993556","Radiology":"#534AB7","Other":"#5F5E5A"
};
const SERVICES = [
  "Gas Refill","Waste Management","Dental","Wrong Parking","Laboratory",
  "Surgical","CT Scan","Renal","Pharmacy","Morgue","Card","ENT",
  "Orthopedic","Xray","Ultrasound","Special Clinic","Physiotherapy",
  "Eye Unit","Attachment","Other"
];
const PAYMENT_MODES = ["Cash","M-PESA","Bank Transfer","Cheque","SHA","AAR","MKL","JUBILEE","OLD MUTUAL","LCT","MTIBA","Waiver","Other"];
const WARDS         = ["Surgical Ward","Pediatric Ward","Medical Ward","Maternity Ward","ICU","Amenity"];

const fmt = n => "KES " + Number(n || 0).toLocaleString("en-KE");
const STATUS_STYLE = {
  "Pending":  { bg:"#fef9c3", color:"#854d0e" },
  "Posted":   { bg:"#dcfce7", color:"#166534" },
  "Verified": { bg:"#dbeafe", color:"#1e40af" },
};

export default function Records() {
  const { user, profile } = useAuth();
  const role   = profile?.role || "viewer";
  const actor  = { uid: user?.uid, name: profile?.name, role };

  const canDelete   = can(role, "deleteRecord");
  const canStatus   = can(role, "changeRecordStatus");
  const canOverride = can(role, "overridePosted");
  const canArchive  = can(role, "archiveRestore");
  const isSuperuser = can(role, "downloadReports");

  const [records,  setRecords]  = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [search,   setSearch]   = useState("");
  const [fStream,  setFStream]  = useState("All");
  const [fStatus,  setFStatus]  = useState("All");
  const [fMonth,   setFMonth]   = useState("All");
  const [sort,     setSort]     = useState({ key: "date", dir: "desc" });
  const [page,     setPage]     = useState(1);
  const [editRec,  setEditRec]  = useState(null);   // superuser override modal
  const [exporting, setExporting] = useState(null); // "pdf" | "docx" | null
  const PER = 20;

  useEffect(() => {
    const q = query(collection(db, "revenue"), orderBy("date", "desc"));
    const unsub = onSnapshot(q, snap => {
      // Exclude archived records from normal view
      setRecords(snap.docs.map(d => ({ id: d.id, ...d.data() })).filter(r => !r.archived));
      setLoading(false);
    });
    return unsub;
  }, []);

  const months = useMemo(() => {
    const s = new Set(records.map(r => r.date?.slice(0, 7)));
    return [...s].sort().reverse();
  }, [records]);

  const filtered = useMemo(() => {
    let r = records.filter(rec => {
      const q = search.toLowerCase();
      return (
        (fStream === "All" || rec.stream === fStream) &&
        (fStatus === "All" || rec.status === fStatus) &&
        (fMonth  === "All" || rec.date?.startsWith(fMonth)) &&
        (!q || [rec.description, rec.receipt, rec.collector, rec.notes]
                .some(f => f?.toLowerCase().includes(q)))
      );
    });
    r.sort((a, b) => {
      let va = a[sort.key], vb = b[sort.key];
      if (typeof va === "string") return sort.dir === "asc" ? va.localeCompare(vb) : vb.localeCompare(va);
      return sort.dir === "asc" ? va - vb : vb - va;
    });
    return r;
  }, [records, search, fStream, fStatus, fMonth, sort]);

  const pages = Math.max(1, Math.ceil(filtered.length / PER));
  const slice = filtered.slice((page - 1) * PER, page * PER);
  const total = filtered.reduce((s, r) => s + (r.amount || 0), 0);

  const toggleSort = k => setSort(s => s.key === k
    ? { ...s, dir: s.dir === "asc" ? "desc" : "asc" }
    : { key: k, dir: "asc" });

  const setStatus = async (id, status, rec) => {
    await updateDoc(doc(db, "revenue", id), { status });
    await logAction(actor, "RECORD_STATUS_CHANGED", { receipt: rec.receipt, oldStatus: rec.status, newStatus: status });
  };

  const deleteRecord = async (r) => {
    if (!window.confirm(`Delete record ${r.receipt}? This cannot be undone.`)) return;
    await deleteDoc(doc(db, "revenue", r.id));
    await logAction(actor, "RECORD_DELETED", { receipt: r.receipt, amount: r.amount, description: r.description });
  };

  const archiveRecord = async (r) => {
    if (!window.confirm(`Archive record ${r.receipt}? It will be hidden from Records but can be restored from System Admin → Archive.`)) return;
    await updateDoc(doc(db, "revenue", r.id), { archived: true });
    await logAction(actor, "RECORD_ARCHIVED", { receipt: r.receipt, amount: r.amount });
  };

  const exportCurrentCSV = () => {
    const headers = ["Date","Receipt","Stream","Description","Amount","PaymentMode","Collector","Status"];
    const escape  = v => { const s = String(v ?? "").replace(/"/g, '""'); return /[",\n]/.test(s) ? `"${s}"` : s; };
    const rows = [
      headers.join(","),
      ...filtered.map(r => [r.date, r.receipt, r.stream, r.description, r.amount || 0, r.paymentMode, r.collector, r.status].map(escape).join(","))
    ];
    const blob = new Blob([rows.join("\r\n")], { type: "text/csv;charset=utf-8;" });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement("a"); a.href = url;
    a.download = `LCRH_Records_filtered.csv`; a.click();
    URL.revokeObjectURL(url);
    logAction(actor, "BULK_CSV_EXPORT", { source: "Records_filtered", count: filtered.length });
  };

  if (loading) return <Spinner />;

  const signatories = { preparedBy: "", checkedBy: "", reviewedBy: profile?.name || "" };
  const recordsExportData = () => ({
    records: filtered,
    filters: { fMonth, fStream, fStatus, search },
    total,
    signatories,
  });

  const handleExportPDF = async () => {
    setExporting("pdf");
    try { await exportRecordsPDF(recordsExportData()); } finally { setExporting(null); }
  };
  const handleExportDocx = async () => {
    setExporting("docx");
    try { await exportRecordsDocx(recordsExportData()); } finally { setExporting(null); }
  };

  const hasActions = canDelete || canOverride || canArchive;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.25rem", flexWrap: "wrap", gap: 10 }}>
        <p style={{ fontWeight: 600, fontSize: 20, margin: 0, color: "#1F3864" }}>Records</p>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {can(role, "bulkExport") && filtered.length > 0 && (
            <button onClick={exportCurrentCSV}
              style={{ display: "flex", alignItems: "center", gap: 6, background: "#1F3864", color: "#fff",
                border: "none", borderRadius: 7, padding: "7px 14px", fontSize: 12, fontWeight: 500, cursor: "pointer" }}>
              <i className="ti ti-download" style={{ fontSize: 15 }} /> Export CSV
            </button>
          )}
          {isSuperuser && filtered.length > 0 && (
            <>
              <button
                onClick={handleExportPDF}
                disabled={!!exporting}
                title="Download as PDF (superuser)"
                style={{
                  display: "flex", alignItems: "center", gap: 6,
                  background: exporting === "pdf" ? "#9ca3af" : "#D85A30",
                  color: "#fff", border: "none", borderRadius: 7,
                  padding: "7px 14px", fontSize: 12, fontWeight: 500,
                  cursor: exporting ? "not-allowed" : "pointer",
                  opacity: exporting && exporting !== "pdf" ? 0.6 : 1,
                }}
              >
                <i className="ti ti-file-type-pdf" style={{ fontSize: 15 }} />
                {exporting === "pdf" ? "Generating…" : "Download PDF"}
              </button>
              <button
                onClick={handleExportDocx}
                disabled={!!exporting}
                title="Download as Word document (superuser)"
                style={{
                  display: "flex", alignItems: "center", gap: 6,
                  background: exporting === "docx" ? "#9ca3af" : "#2563EB",
                  color: "#fff", border: "none", borderRadius: 7,
                  padding: "7px 14px", fontSize: 12, fontWeight: 500,
                  cursor: exporting ? "not-allowed" : "pointer",
                  opacity: exporting && exporting !== "docx" ? 0.6 : 1,
                }}
              >
                <i className="ti ti-file-type-doc" style={{ fontSize: 15 }} />
                {exporting === "docx" ? "Generating…" : "Download Word"}
              </button>
            </>
          )}
        </div>
      </div>

      {/* Filters */}
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 14 }}>
        <input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }}
          placeholder="Search description, receipt, collector…" style={{ flex: "1 1 200px", minWidth: 0 }} />
        <select value={fStream} onChange={e => { setFStream(e.target.value); setPage(1); }} style={{ minWidth: 130 }}>
          <option>All</option>{STREAMS.map(s => <option key={s}>{s}</option>)}
        </select>
        <select value={fStatus} onChange={e => { setFStatus(e.target.value); setPage(1); }} style={{ minWidth: 110 }}>
          {["All","Pending","Posted","Verified"].map(s => <option key={s}>{s}</option>)}
        </select>
        <select value={fMonth} onChange={e => { setFMonth(e.target.value); setPage(1); }} style={{ minWidth: 130 }}>
          <option value="All">All months</option>
          {months.map(m => <option key={m} value={m}>{m}</option>)}
        </select>
      </div>

      {records.length === 0 ? (
        <div style={{ textAlign: "center", padding: "4rem", background: "#fff", borderRadius: 12, border: "1px solid #e5e7eb" }}>
          <i className="ti ti-table-off" style={{ fontSize: 48, color: "#d1d5db", display: "block", marginBottom: 12 }} />
          <p style={{ color: "#6b7280" }}>No records yet. Use Revenue Entry to add the first record.</p>
        </div>
      ) : (
        <>
          <div style={{ overflowX: "auto", borderRadius: 12, border: "1px solid #e5e7eb" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
              <thead>
                <tr style={{ background: "#f9fafb" }}>
                  {[["date","Date"],["receipt","Receipt"],["stream","Stream"],["description","Description"],
                    ["amount","Amount"],["paymentMode","Mode"],["collector","Collector"],["status","Status"]].map(([k, l]) => (
                    <th key={k} onClick={() => toggleSort(k)} style={{
                      padding: "10px 12px", textAlign: "left", fontWeight: 500,
                      color: "#6b7280", fontSize: 11, cursor: "pointer",
                      whiteSpace: "nowrap", userSelect: "none", borderBottom: "1px solid #e5e7eb"
                    }}>
                      {l} {sort.key === k ? (sort.dir === "asc" ? "↑" : "↓") : ""}
                    </th>
                  ))}
                  {hasActions && <th style={{ padding: "10px 12px", borderBottom: "1px solid #e5e7eb" }} />}
                </tr>
              </thead>
              <tbody>
                {slice.map((r, i) => {
                  const ss = STATUS_STYLE[r.status] || STATUS_STYLE["Pending"];
                  return (
                    <tr key={r.id} style={{ borderBottom: "1px solid #f9fafb", background: i % 2 ? "#fafafa" : "#fff" }}>
                      <td style={{ padding: "9px 12px", whiteSpace: "nowrap" }}>{r.date}</td>
                      <td style={{ padding: "9px 12px", fontFamily: "monospace", fontSize: 11, color: "#6b7280" }}>{r.receipt}</td>
                      <td style={{ padding: "9px 12px" }}>
                        <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}>
                          <span style={{ width: 7, height: 7, borderRadius: 2, background: STREAM_COLORS[r.stream], display: "inline-block" }} />
                          {r.stream}
                        </span>
                      </td>
                      <td style={{ padding: "9px 12px", maxWidth: 200, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.description}</td>
                      <td style={{ padding: "9px 12px", fontWeight: 600, whiteSpace: "nowrap", color: "#1F3864" }}>{fmt(r.amount)}</td>
                      <td style={{ padding: "9px 12px", color: "#6b7280" }}>{r.paymentMode}</td>
                      <td style={{ padding: "9px 12px" }}>{r.collector}</td>
                      <td style={{ padding: "9px 12px" }}>
                        {canStatus ? (
                          <select value={r.status} onChange={e => setStatus(r.id, e.target.value, r)}
                            style={{ fontSize: 11, padding: "3px 6px", borderRadius: 20,
                              background: ss.bg, color: ss.color, border: "none", cursor: "pointer", fontWeight: 500 }}>
                            {["Pending","Posted","Verified"].map(s => <option key={s}>{s}</option>)}
                          </select>
                        ) : (
                          <span style={{ background: ss.bg, color: ss.color, borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 500 }}>{r.status}</span>
                        )}
                      </td>
                      {hasActions && (
                        <td style={{ padding: "9px 12px" }}>
                          <div style={{ display: "flex", gap: 4 }}>
                            {canOverride && (
                              <button onClick={() => setEditRec(r)} title="Override/edit record"
                                style={{ background: "none", border: "none", color: "#6b21a8", cursor: "pointer", fontSize: 15, padding: 2 }}>
                                <i className="ti ti-edit" />
                              </button>
                            )}
                            {canArchive && (
                              <button onClick={() => archiveRecord(r)} title="Archive record"
                                style={{ background: "none", border: "none", color: "#ca8a04", cursor: "pointer", fontSize: 15, padding: 2 }}>
                                <i className="ti ti-archive" />
                              </button>
                            )}
                            {canDelete && (
                              <button onClick={() => deleteRecord(r)} title="Delete record"
                                style={{ background: "none", border: "none", color: "#dc2626", cursor: "pointer", fontSize: 15, padding: 2 }}>
                                <i className="ti ti-trash" />
                              </button>
                            )}
                          </div>
                        </td>
                      )}
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr style={{ borderTop: "2px solid #e5e7eb", background: "#f9fafb" }}>
                  <td colSpan={4} style={{ padding: "10px 12px", fontSize: 12, color: "#6b7280" }}>
                    {filtered.length} records shown
                  </td>
                  <td style={{ padding: "10px 12px", fontWeight: 700, fontSize: 14, color: "#1F3864" }}>{fmt(total)}</td>
                  <td colSpan={hasActions ? 4 : 3} />
                </tr>
              </tfoot>
            </table>
          </div>

          {/* Pagination */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12 }}>
            <span style={{ fontSize: 12, color: "#9ca3af" }}>Page {page} of {pages}</span>
            <div style={{ display: "flex", gap: 6 }}>
              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
                style={{ padding: "6px 14px", fontSize: 12, borderRadius: 6, cursor: "pointer", border: "1px solid #e5e7eb" }}>← Prev</button>
              <button onClick={() => setPage(p => Math.min(pages, p + 1))} disabled={page === pages}
                style={{ padding: "6px 14px", fontSize: 12, borderRadius: 6, cursor: "pointer", border: "1px solid #e5e7eb" }}>Next →</button>
            </div>
          </div>
        </>
      )}

      {/* Override/Edit Modal — SuperUser only */}
      {editRec && (
        <OverrideModal
          record={editRec}
          actor={actor}
          onClose={() => setEditRec(null)}
        />
      )}
    </div>
  );
}

// ─── Override Modal ──────────────────────────────────────────────────────────
function OverrideModal({ record, actor, onClose }) {
  const [form, setForm]   = useState({ ...record });
  const [busy, setBusy]   = useState(false);
  const [err,  setErr]    = useState("");

  const set = k => e => setForm(f => ({ ...f, [k]: e.target.value }));

  const totalBill    = parseFloat(form.totalBill)    || 0;
  const amountPaid   = parseFloat(form.amountPaid)   || 0;
  const amountWaived = parseFloat(form.amountWaived) || 0;
  const balance      = totalBill - amountPaid - amountWaived;

  const save = async () => {
    if (amountPaid + amountWaived > totalBill) {
      setErr("Amount paid + waived cannot exceed total bill."); return;
    }
    setErr(""); setBusy(true);
    try {
      const updates = {
        date:          form.date,
        stream:        form.stream,
        service:       form.service,
        admissionType: form.admissionType,
        ward:          form.admissionType === "Inpatient" ? form.ward : "",
        description:   form.description,
        totalBill:     totalBill,
        amountPaid:    amountPaid,
        amountWaived:  amountWaived,
        amount:        amountPaid,   // keep amount field in sync
        paymentMode:   form.paymentMode,
        collector:     form.collector,
        notes:         form.notes,
        status:        form.status,
        overriddenAt:  new Date().toISOString(),
        overriddenBy:  actor.name,
      };
      await updateDoc(doc(db, "revenue", record.id), updates);
      await logAction(actor, "RECORD_OVERRIDDEN", {
        receipt: record.receipt,
        changes: Object.keys(updates).filter(k => String(updates[k]) !== String(record[k]))
      });
      onClose();
    } catch (e) {
      setErr(e.message);
    } finally { setBusy(false); }
  };

  const lbl = { fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 4 };
  const inp = { width: "100%", boxSizing: "border-box" };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", display: "flex",
      alignItems: "flex-start", justifyContent: "center", zIndex: 200, overflowY: "auto", padding: "2rem 1rem" }}>
      <div style={{ background: "#fff", borderRadius: 14, padding: "1.5rem", width: "100%", maxWidth: 580 }}>
        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
          <div>
            <p style={{ fontWeight: 700, fontSize: 16, color: "#6b21a8", margin: 0 }}>
              <i className="ti ti-edit" style={{ marginRight: 6 }} />Override Record
            </p>
            <p style={{ fontSize: 11, color: "#9ca3af", margin: "2px 0 0" }}>Receipt: {record.receipt}</p>
          </div>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 20, cursor: "pointer", color: "#9ca3af" }}>×</button>
        </div>

        <div style={{ background: "#fdf4ff", border: "1px solid #e9d5ff", borderRadius: 8, padding: "8px 12px", fontSize: 12, color: "#7c3aed", marginBottom: "1rem" }}>
          ⚠️ SuperUser override — changes are logged in the audit trail.
        </div>

        {err && <div style={{ background: "#fef2f2", border: "1px solid #fecaca", color: "#dc2626", borderRadius: 8, padding: "8px 12px", fontSize: 12, marginBottom: 14 }}>{err}</div>}

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <div>
            <label style={lbl}>Date</label>
            <input type="date" value={form.date} onChange={set("date")} style={inp} />
          </div>
          <div>
            <label style={lbl}>Status</label>
            <select value={form.status} onChange={set("status")} style={inp}>
              {["Pending","Posted","Verified"].map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label style={lbl}>Stream</label>
            <select value={form.stream} onChange={set("stream")} style={inp}>
              {["OPD Fees","IPD Charges","Lab Services","Pharmacy","Maternity","Radiology","Other"].map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label style={lbl}>Service</label>
            <select value={form.service} onChange={set("service")} style={inp}>
              {SERVICES.map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label style={lbl}>Admission Type</label>
            <select value={form.admissionType} onChange={set("admissionType")} style={inp}>
              {["Outpatient","Inpatient"].map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
          {form.admissionType === "Inpatient" && (
            <div>
              <label style={lbl}>Ward</label>
              <select value={form.ward} onChange={set("ward")} style={inp}>
                <option value="">Select ward</option>
                {WARDS.map(w => <option key={w}>{w}</option>)}
              </select>
            </div>
          )}
          <div style={{ gridColumn: "1 / -1" }}>
            <label style={lbl}>Description</label>
            <input value={form.description} onChange={set("description")} style={inp} />
          </div>
          <div>
            <label style={lbl}>Total Bill (KES)</label>
            <input type="number" value={form.totalBill} onChange={set("totalBill")} style={inp} min="0" />
          </div>
          <div>
            <label style={lbl}>Amount Paid (KES)</label>
            <input type="number" value={form.amountPaid} onChange={set("amountPaid")} style={inp} min="0" />
          </div>
          <div>
            <label style={lbl}>Amount Waived (KES)</label>
            <input type="number" value={form.amountWaived} onChange={set("amountWaived")} style={inp} min="0" />
          </div>
          <div>
            <label style={lbl}>Balance</label>
            <div style={{ padding: "9px 12px", background: "#f9fafb", borderRadius: 6, border: "1px solid #e5e7eb", fontSize: 14, fontWeight: 600, color: balance < 0 ? "#dc2626" : "#1F3864" }}>
              KES {balance.toLocaleString("en-KE")}
            </div>
          </div>
          <div>
            <label style={lbl}>Payment Mode</label>
            <select value={form.paymentMode} onChange={set("paymentMode")} style={inp}>
              {PAYMENT_MODES.map(p => <option key={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label style={lbl}>Collector</label>
            <input value={form.collector} onChange={set("collector")} style={inp} />
          </div>
          <div style={{ gridColumn: "1 / -1" }}>
            <label style={lbl}>Notes</label>
            <textarea value={form.notes} onChange={set("notes")} rows={2} style={{ ...inp, resize: "vertical" }} />
          </div>
        </div>

        <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
          <button onClick={save} disabled={busy}
            style={{ background: busy ? "#a78bfa" : "#6b21a8", color: "#fff", border: "none", borderRadius: 8,
              padding: "10px 20px", fontWeight: 600, fontSize: 14, cursor: busy ? "not-allowed" : "pointer" }}>
            {busy ? "Saving…" : "Save Override"}
          </button>
          <button onClick={onClose}
            style={{ background: "transparent", border: "1px solid #d1d5db", borderRadius: 8,
              padding: "10px 20px", fontSize: 14, color: "#6b7280", cursor: "pointer" }}>Cancel</button>
        </div>
      </div>
    </div>
  );
}

function Spinner() {
  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "4rem" }}>
      <div style={{ width: 36, height: 36, border: "3px solid #e5e7eb", borderTopColor: "#1F3864", borderRadius: "50%", animation: "spin 0.8s linear infinite" }} />
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}
