import React, { useState } from "react";
import { AuthProvider, useAuth } from "./firebase/AuthContext";
import Login          from "./components/Login";
import Sidebar        from "./components/Sidebar";
import Dashboard      from "./components/Dashboard";
import RevenueEntry   from "./components/RevenueEntry";
import Records        from "./components/Records";
import Analytics      from "./components/Analytics";
import Reports        from "./components/Reports";
import Insurance      from "./components/Insurance";
import UserManagement from "./components/UserManagement";
import SystemAdmin    from "./components/SystemAdmin";
import Settings       from "./components/Settings";

const MOBILE_NAV = [
  { id: "dashboard",  label: "Home",      icon: "ti-layout-dashboard", roles: ["superuser","admin","finance","viewer"] },
  { id: "entry",      label: "Entry",     icon: "ti-plus-circle",      roles: ["superuser","admin","finance"] },
  { id: "insurance",  label: "Insurance", icon: "ti-heart-handshake",  roles: ["superuser","admin","finance","viewer"] },
  { id: "records",    label: "Records",   icon: "ti-table",            roles: ["superuser","admin","finance","viewer"] },
  { id: "more",       label: "More",      icon: "ti-dots",             roles: ["superuser","admin","finance","viewer"] },
];

function BottomNav({ page, setPage, role }) {
  return (
    <div className="bottom-nav" style={{ display: "flex" }}>
      {MOBILE_NAV.filter(n => n.roles.includes(role)).map(n => {
        const active = page === n.id || (n.id === "more" && ["analytics","reports","users","settings"].includes(page));
        return (
          <button key={n.id} onClick={() => setPage(n.id)} style={{
            flex: 1, display: "flex", flexDirection: "column", alignItems: "center",
            justifyContent: "center", padding: "10px 0 8px",
            background: "transparent", border: "none",
            color: active ? "#C9A84C" : "rgba(255,255,255,0.55)",
            cursor: "pointer", gap: 3
          }}>
            <i className={`ti ${n.icon}`} style={{ fontSize: 22 }} />
            <span style={{ fontSize: 10, fontWeight: active ? 600 : 400 }}>{n.label}</span>
          </button>
        );
      })}
    </div>
  );
}

function MoreMenu({ setPage, role, onClose }) {
  const items = [
    { id: "analytics", label: "Analytics",       icon: "ti-chart-bar",      roles: ["superuser","admin","finance","viewer"] },
    { id: "reports",   label: "Reports",         icon: "ti-file-analytics", roles: ["superuser","admin","finance","viewer"] },
    { id: "users",     label: "User Management", icon: "ti-users",          roles: ["superuser","admin"] },
    { id: "sysadmin",  label: "System Admin",    icon: "ti-shield-cog",     roles: ["superuser"] },
    { id: "settings",  label: "Settings",        icon: "ti-settings",       roles: ["superuser","admin","finance","viewer"] },
  ].filter(i => i.roles.includes(role));

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 80, display: "flex", flexDirection: "column", justifyContent: "flex-end" }}>
      <div onClick={onClose} style={{ flex: 1, background: "rgba(0,0,0,0.4)" }} />
      <div style={{ background: "#fff", borderRadius: "20px 20px 0 0", padding: "1rem 1rem 2rem" }}>
        <div style={{ width: 36, height: 4, borderRadius: 2, background: "#d1d5db", margin: "0 auto 1.25rem" }} />
        <p style={{ fontWeight: 600, fontSize: 14, color: "#1F3864", margin: "0 0 1rem", paddingLeft: 8 }}>More options</p>
        {items.map(item => (
          <button key={item.id} onClick={() => { setPage(item.id); onClose(); }} style={{
            display: "flex", alignItems: "center", gap: 14, width: "100%",
            padding: "14px 12px", background: "transparent", border: "none",
            borderRadius: 10, cursor: "pointer", fontSize: 15, color: "#1F3864", textAlign: "left"
          }}>
            <div style={{ width: 40, height: 40, borderRadius: 10, background: "#f0f4f9", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <i className={`ti ${item.icon}`} style={{ fontSize: 20, color: "#1F3864" }} />
            </div>
            {item.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function AppShell() {
  const { user, profile, loading } = useAuth();
  const [page,     setPage]     = useState("dashboard");
  const [showMore, setShowMore] = useState(false);

  if (loading) {
    return (
      <div style={{ display:"flex", alignItems:"center", justifyContent:"center", height:"100vh", background:"#f5f6fa" }}>
        <div>
          <div style={{ width:40, height:40, border:"3px solid #e5e7eb", borderTopColor:"#1F3864", borderRadius:"50%", animation:"spin 0.8s linear infinite", margin:"0 auto 12px" }} />
          <p style={{ color:"#9ca3af", fontSize:13, textAlign:"center" }}>Loading…</p>
          <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
        </div>
      </div>
    );
  }

  if (!user) return <Login />;

  const role = profile?.role || "viewer";

  const allowed = {
    dashboard: true, entry: ["superuser","admin","finance"].includes(role),
    records: true, analytics: true, reports: true,
    insurance: true, users: ["superuser","admin"].includes(role),
    sysadmin: role === "superuser", settings: true, more: true,
  };

  const handleSetPage = (p) => {
    if (p === "more") { setShowMore(true); return; }
    setPage(p); setShowMore(false);
  };

  const activePage = allowed[page] ? page : "dashboard";

  const PAGE = {
    dashboard: <Dashboard />, entry: <RevenueEntry />, records: <Records />,
    analytics: <Analytics />, reports: <Reports />, insurance: <Insurance />,
    users: <UserManagement />, sysadmin: <SystemAdmin />, settings: <Settings />,
  };

  return (
    <div style={{ display:"flex", minHeight:"100vh" }}>
      <div className="sidebar-desktop">
        <Sidebar page={activePage} setPage={setPage} />
      </div>
      <main className="main-content" style={{
        flex:1, padding:"1.75rem 2rem", overflowY:"auto", minWidth:0, background:"#f5f6fa"
      }}>
        {PAGE[activePage]}
      </main>
      <BottomNav page={activePage} setPage={handleSetPage} role={role} />
      {showMore && <MoreMenu setPage={p => { setPage(p); }} role={role} onClose={() => setShowMore(false)} />}
    </div>
  );
}

export default function App() {
  return <AuthProvider><AppShell /></AuthProvider>;
}
