// Reads system configuration from Firestore config/app_config.
// Falls back to hardcoded defaults if the document doesn't exist yet.
import { useState, useEffect } from "react";
import { db } from "../firebase/config";
import { doc, onSnapshot } from "firebase/firestore";

export const CONFIG_DEFAULTS = {
  services:  [
    "Gas Refill","Waste Management","Dental","Wrong Parking","Laboratory",
    "Surgical","CT Scan","Renal","Pharmacy","Morgue","Card","ENT",
    "Orthopedic","Xray","Ultrasound","Special Clinic","Physiotherapy",
    "Eye Unit","Attachment","Other"
  ],
  wards:     ["Surgical Ward","Pediatric Ward","Medical Ward","Maternity Ward","ICU","Amenity"],
  streams:   ["OPD Fees","IPD Charges","Lab Services","Pharmacy","Maternity","Radiology","Other"],
  insurance: ["SHA","AAR","MKL","JUBILEE","OLD MUTUAL","LCT","MTIBA"],
};

export function useConfig() {
  const [config, setConfig] = useState(CONFIG_DEFAULTS);

  useEffect(() => {
    const unsub = onSnapshot(doc(db, "config", "app_config"), snap => {
      if (snap.exists()) {
        setConfig(prev => ({ ...prev, ...snap.data() }));
      } else {
        setConfig(CONFIG_DEFAULTS);
      }
    });
    return unsub;
  }, []);

  return config;
}
