import React, { useEffect, useState } from "react";
import { db, auth } from "../firebase/config";
import {
  collection, onSnapshot, doc, setDoc, updateDoc, deleteDoc
} from "firebase/firestore";
import { createUserWithEmailAndPassword } from "firebase/auth";
import { useAuth } from "../firebase/AuthContext";
import { can, ROLES, ROLE_DESC, ROLE_BADGE } from "../utils/permissions";
import { logAction } from "../utils/audit";

export default function UserManagement() {
  const { user, profile } = useAuth();
  const actor = { uid: user?.uid, name: profile?.name, role: profile?.role };
  const isSuperUser = profile?.role === "superuser";

  const [users,  setUsers]  = useState([]);
  const [form,   setForm]   = useState({ name: "", email: "", role: "finance", password: "" });
  const [busy,   setBusy]   = useState(false);
  const [msg,    setMsg]    = useState({ text: "", type: "" });
  const [confirmDelete, setConfirmDelete] = useState(null); // userId to delete

  useEffect(() => {
    const unsub = onSnapshot(collection(db, "users"), snap =>
      setUsers(snap.docs.map(d => ({ id: d.id, ...d.data() })))
    );
    return unsub;
  }, []);

  const set = k => e => setForm(f => ({ ...f, [k]: e.target.value }));

  const addUser = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.password) {
      setMsg({ text: "Name, email and password are required.", type: "err" }); return;
    }
    if (form.password.length < 6) {
      setMsg({ text: "Password must be at least 6 characters.", type: "err" }); return;
    }
    setBusy(true); setMsg({ text: "", type: "" });
    try {
      const cred = await createUserWithEmailAndPassword(auth, form.email.trim(), form.password);
      await setDoc(doc(db, "users", cred.user.uid), {
        name:      form.name.trim(),
        email:     form.email.trim().toLowerCase(),
        role:      form.role,
        active:    true,
        createdAt: new Date().toISOString(),
      });
      await logAction(actor, "USER_CREATED", { name: form.name.trim(), email: form.email.trim(), role: form.role });
      setMsg({ text: `✓ User "${form.name}" created. They can now log in and use "Forgot password?" to set their own password.`, type: "ok" });
      setForm({ name: "", email: "", role: "finance", password: "" });
    } catch (ex) {
      const map = {
        "auth/email-already-in-use": "That email is already registered in the system.",
        "auth/weak-password":        "Password must be at least 6 characters.",
        "auth/invalid-email":        "Invalid email address format.",
      };
      setMsg({ text: map[ex.code] || ex.message, type: "err" });
    } finally { setBusy(false); }
  };

  const toggleActive = async (userId, current) => {
    const u = users.find(u => u.id === userId);
    await updateDoc(doc(db, "users", userId), { active: !current });
    await logAction(actor, current ? "USER_DEACTIVATED" : "USER_ACTIVATED", { name: u?.name, email: u?.email });
    setMsg({ text: `User ${current ? "deactivated" : "activated"} successfully.`, type: "ok" });
    setTimeout(() => setMsg({ text: "", type: "" }), 3000);
  };

  const changeRole = async (userId, role) => {
    const u = users.find(u => u.id === userId);
    await updateDoc(doc(db, "users", userId), { role });
    await logAction(actor, "USER_ROLE_CHANGED", { name: u?.name, email: u?.email, newRole: role });
  };

  // Delete from Firestore (blocks access immediately since profile drives role)
  const deleteUser = async (userId) => {
    const u = users.find(u => u.id === userId);
    await deleteDoc(doc(db, "users", userId));
    await logAction(actor, "USER_DELETED", { name: u?.name, email: u?.email });
    setConfirmDelete(null);
    setMsg({ text: "User removed from the system. They can no longer access any data.", type: "ok" });
    setTimeout(() => setMsg({ text: "", type: "" }), 4000);
  };

  const initials = name => (name || "?").split(" ").map(w => w[0]).join("").toUpperCase().slice(0, 2);

  // ROLE_BADGE imported from permissions.js

  return (
    <div>
      <p style={{ fontWeight: 600, fontSize: 20, margin: "0 0 1.5rem", color: "#1F3864" }}>User management</p>

      {/* Global message */}
      {msg.text && (
        <div style={{
          background: msg.type === "ok" ? "#f0fdf4" : "#fef2f2",
          border: `1px solid ${msg.type === "ok" ? "#86efac" : "#fecaca"}`,
          color: msg.type === "ok" ? "#166534" : "#dc2626",
          borderRadius: 10, padding: "12px 16px", fontSize: 13, marginBottom: 18
        }}>{msg.text}</div>
      )}

      {/* Delete confirmation modal */}
      {confirmDelete && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.4)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }}>
          <div style={{ background: "#fff", borderRadius: 14, padding: "2rem", width: 400, maxWidth: "90vw" }}>
            <p style={{ fontWeight: 600, fontSize: 16, margin: "0 0 8px", color: "#991b1b" }}>Remove user?</p>
            <p style={{ fontSize: 14, color: "#6b7280", margin: "0 0 1.5rem" }}>
              This removes <strong>{users.find(u => u.id === confirmDelete)?.name}</strong> from the system.
              They will immediately lose access to all data and reports.
              <br /><br />
              <span style={{ fontSize: 12, color: "#9ca3af" }}>Note: Their login account remains in Firebase Auth. To fully delete it, go to Firebase Console → Authentication → Users.</span>
            </p>
            <div style={{ display: "flex", gap: 10 }}>
              <button onClick={() => deleteUser(confirmDelete)} style={{
                background: "#dc2626", color: "#fff", border: "none", borderRadius: 8,
                padding: "10px 20px", fontWeight: 600, fontSize: 14, cursor: "pointer"
              }}>Yes, remove user</button>
              <button onClick={() => setConfirmDelete(null)} style={{
                background: "transparent", border: "1px solid #d1d5db", borderRadius: 8,
                padding: "10px 20px", fontSize: 14, color: "#6b7280", cursor: "pointer"
              }}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Add user form */}
      <div style={{ background: "#fff", border: "1px solid #e5e7eb", borderRadius: 14, padding: "1.5rem", marginBottom: 24, maxWidth: 620 }}>
        <p style={{ fontWeight: 600, fontSize: 15, margin: "0 0 0.25rem", color: "#1F3864" }}>Add new user</p>
        <p style={{ fontSize: 12, color: "#9ca3af", margin: "0 0 1.25rem" }}>
          Use their real work email — they can use "Forgot password?" on the login screen to set their own password anytime.
        </p>

        <form onSubmit={addUser}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
            <div>
              <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>Full name *</label>
              <input value={form.name} onChange={set("name")} placeholder="e.g. Jane Auma" style={{ width: "100%", boxSizing: "border-box" }} required />
            </div>
            <div>
              <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>Email address *</label>
              <input type="email" value={form.email} onChange={set("email")} placeholder="jane@lcrh.go.ke" style={{ width: "100%", boxSizing: "border-box" }} required />
            </div>
            <div>
              <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>Role</label>
              <select value={form.role} onChange={set("role")} style={{ width: "100%", boxSizing: "border-box" }}>
                {ROLES.filter(r => isSuperUser || r !== "superuser").map(r => (
                  <option key={r} value={r}>{r.charAt(0).toUpperCase() + r.slice(1)}</option>
                ))}
              </select>
              <p style={{ fontSize: 11, color: "#9ca3af", margin: "4px 0 0" }}>{ROLE_DESC[form.role]}</p>
            </div>
            <div>
              <label style={{ fontSize: 12, fontWeight: 500, color: "#374151", display: "block", marginBottom: 5 }}>Temporary password *</label>
              <input type="password" value={form.password} onChange={set("password")} placeholder="Min 6 characters" style={{ width: "100%", boxSizing: "border-box" }} required />
              <p style={{ fontSize: 11, color: "#9ca3af", margin: "4px 0 0" }}>They can change this via Settings after first login.</p>
            </div>
          </div>
          <button type="submit" disabled={busy} style={{
            marginTop: 16, background: busy ? "#93a3c0" : "#1F3864", color: "#fff",
            border: "none", borderRadius: 8, padding: "10px 24px",
            fontWeight: 600, fontSize: 14, cursor: busy ? "not-allowed" : "pointer"
          }}>
            {busy ? "Creating…" : "Create user"}
          </button>
        </form>
      </div>

      {/* Password reset info box */}
      <div style={{ background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 10, padding: "12px 16px", fontSize: 13, color: "#1e40af", marginBottom: 20, display: "flex", gap: 10, alignItems: "flex-start" }}>
        <i className="ti ti-info-circle" style={{ fontSize: 18, flexShrink: 0, marginTop: 1 }} />
        <div>
          <strong>Password reset:</strong> Any user can reset their own password by clicking <em>"Forgot password?"</em> on the login screen. A reset link is sent to their registered email address instantly.
        </div>
      </div>

      {/* Users list */}
      <div style={{ background: "#fff", border: "1px solid #e5e7eb", borderRadius: 12, overflow: "hidden" }}>
        <div style={{ padding: "1rem 1.5rem", borderBottom: "1px solid #f3f4f6", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <p style={{ fontWeight: 500, fontSize: 14, margin: 0, color: "#1F3864" }}>
            {users.length} system {users.length === 1 ? "user" : "users"}
          </p>
          <span style={{ fontSize: 12, color: "#9ca3af" }}>Admins can change roles, activate/deactivate, and remove users</span>
        </div>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ background: "#f9fafb" }}>
              {["User", "Email", "Role", "Status", "Actions"].map(h => (
                <th key={h} style={{ padding: "10px 16px", textAlign: "left", fontWeight: 500, color: "#6b7280", fontSize: 11, borderBottom: "1px solid #e5e7eb" }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {users.length === 0 ? (
              <tr><td colSpan={5} style={{ padding: "2rem", textAlign: "center", color: "#9ca3af" }}>No users yet.</td></tr>
            ) : (
              users.sort((a, b) => (a.name || "").localeCompare(b.name || "")).map((u, i) => (
                <tr key={u.id} style={{ borderBottom: "1px solid #f9fafb", background: i % 2 ? "#fafafa" : "#fff" }}>
                  {/* Name */}
                  <td style={{ padding: "12px 16px" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <div style={{
                        width: 34, height: 34, borderRadius: "50%", background: "#1F3864",
                        display: "flex", alignItems: "center", justifyContent: "center",
                        fontSize: 11, fontWeight: 600, color: "#C9A84C", flexShrink: 0
                      }}>{initials(u.name)}</div>
                      <span style={{ fontWeight: 500 }}>{u.name}</span>
                    </div>
                  </td>

                  {/* Email */}
                  <td style={{ padding: "12px 16px", color: "#6b7280", fontSize: 12 }}>{u.email}</td>

                  {/* Role selector */}
                  <td style={{ padding: "12px 16px" }}>
                    <select value={u.role} onChange={e => changeRole(u.id, e.target.value)}
                      style={{
                        fontSize: 12, padding: "4px 10px", borderRadius: 20,
                        background: ROLE_BADGE[u.role]?.bg || "#f3f4f6",
                        color: ROLE_BADGE[u.role]?.color || "#374151",
                        border: "none", cursor: "pointer", fontWeight: 500
                      }}>
                      {ROLES.filter(r => isSuperUser || r !== "superuser").map(r => (
                        <option key={r} value={r}>{r.charAt(0).toUpperCase() + r.slice(1)}</option>
                      ))}
                    </select>
                  </td>

                  {/* Status */}
                  <td style={{ padding: "12px 16px" }}>
                    <span style={{
                      background: u.active ? "#dcfce7" : "#f3f4f6",
                      color: u.active ? "#166534" : "#6b7280",
                      borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 500
                    }}>{u.active ? "Active" : "Inactive"}</span>
                  </td>

                  {/* Actions */}
                  <td style={{ padding: "12px 16px" }}>
                    <div style={{ display: "flex", gap: 8 }}>
                      <button onClick={() => toggleActive(u.id, u.active)} style={{
                        fontSize: 12, padding: "5px 12px", borderRadius: 6,
                        border: `1px solid ${u.active ? "#fca5a5" : "#86efac"}`,
                        background: "transparent",
                        cursor: "pointer",
                        color: u.active ? "#dc2626" : "#166534"
                      }}>
                        {u.active ? "Deactivate" : "Activate"}
                      </button>
                      <button onClick={() => setConfirmDelete(u.id)} style={{
                        fontSize: 12, padding: "5px 10px", borderRadius: 6,
                        border: "1px solid #fca5a5", background: "transparent",
                        cursor: "pointer", color: "#dc2626",
                        display: "flex", alignItems: "center", gap: 4
                      }} title="Remove user from system">
                        <i className="ti ti-trash" style={{ fontSize: 14 }} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <div style={{ marginTop: 14, background: "#fffbeb", border: "1px solid #fde68a", borderRadius: 8, padding: "12px 16px", fontSize: 12, color: "#92400e" }}>
        <strong>Deactivate vs Remove:</strong> Deactivating blocks login but keeps the user's records intact. Removing deletes the user profile — their past entries remain but they cannot log in. For complete account deletion, visit Firebase Console → Authentication → Users.
      </div>
    </div>
  );
}
