// Audit logging utility — writes to Firestore audit_logs collection
import { db } from "../firebase/config";
import { collection, addDoc, serverTimestamp } from "firebase/firestore";

/**
 * Log a user action to the audit_logs Firestore collection.
 * Non-blocking — failures are silently swallowed so they never break UI.
 *
 * @param {{ uid: string, name: string, role: string }} actor
 * @param {string} action  e.g. "RECORD_DELETED", "USER_CREATED"
 * @param {object} details  arbitrary key/value context
 */
export const logAction = async (actor, action, details = {}) => {
  try {
    await addDoc(collection(db, "audit_logs"), {
      userId:   actor?.uid    || "unknown",
      userName: actor?.name   || actor?.email || "unknown",
      userRole: actor?.role   || "unknown",
      action,
      details,
      ts: serverTimestamp(),
    });
  } catch (e) {
    console.warn("[Audit] Failed to write log:", e);
  }
};
