import React, { useEffect, useState, useMemo } from "react";
import { db } from "../firebase/config";
import { collection, onSnapshot, query, orderBy } from "firebase/firestore";
import {
  BarChart, Bar, LineChart, Line, AreaChart, Area,
  PieChart, Pie, Cell, RadialBarChart, RadialBar,
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  Legend, Treemap, FunnelChart, Funnel, LabelList, PolarAngleAxis
} from "recharts";

/* ─── constants ─────────────────────────────────────────────── */
const NAVY   = "#1F3864";
const GOLD   = "#C9A84C";
const GREEN  = "#1D9E75";
const RED    = "#D85A30";
const PURPLE = "#534AB7";
const TEAL   = "#0e7490";
const PINK   = "#993556";
const GRAY   = "#6b7280";

const STREAM_COLORS = {
  "OPD Fees":     NAVY,
  "IPD Charges":  GREEN,
  "Lab Services": GOLD,
  "Pharmacy":     RED,
  "Maternity":    PINK,
  "Radiology":    PURPLE,
  "Surgical":     TEAL,
  "CT Scan":      "#0369a1",
  "Renal":        "#7c3aed",
  "Morgue":       "#374151",
  "Card":         "#059669",
  "ENT":          "#d97706",
  "Other":        GRAY,
};

const CHANNEL_COLORS = {
  "Cash":      "#166534",
  "M-PESA":    "#15803d",
  "Insurance": NAVY,
  "Bank":      TEAL,
  "Other":     GRAY,
};

const CLAIM_STATUS_COLORS = {
  "Submitted":    GOLD,
  "Under Review": PURPLE,
  "Approved":     GREEN,
  "Rejected":     RED,
  "Paid":         NAVY,
};

const SCHEME_COLORS = [NAVY, GREEN, GOLD, RED, PURPLE, TEAL, PINK, "#d97706"];

const PAYMENT_MODES_RAW = ["Cash","M-PESA","Bank Transfer","Cheque","SHA","AAR","MKL","JUBILEE","OLD MUTUAL","LCT","MTIBA","Waiver","Other"];
const INSURANCE_SCHEMES  = ["SHA","AAR","MKL","JUBILEE","OLD MUTUAL","LCT","MTIBA"];
const CLAIM_STATUSES     = ["Submitted","Under Review","Approved","Rejected","Paid"];

const WARDS = ["General Ward","Maternity","Paediatric","ICU","Surgical","Medical","Isolation","Other"];

const fmt      = n   => "KES " + Number(n||0).toLocaleString("en-KE");
const fmtShort = n   => { n = Number(n||0); return n>=1e6 ? `KES ${(n/1e6).toFixed(2)}M` : n>=1e3 ? `KES ${(n/1e3).toFixed(1)}K` : `KES ${n}`; };
const pct      = (a,b) => b ? ((a/b)*100).toFixed(1)+"%" : "—";

/* channel grouping */
const channelOf = r => {
  const pm = r.paymentMode || "";
  if (pm === "Cash")                     return "Cash";
  if (pm === "M-PESA")                   return "M-PESA";
  if (INSURANCE_SCHEMES.includes(pm))    return "Insurance";
  if (pm === "Bank Transfer"||pm==="Cheque") return "Bank";
  return "Other";
};

/* ─── financial year helpers ────────────────────────────────── */
const fyOf = dateStr => {
  const d = new Date(dateStr);
  if (!dateStr || isNaN(d)) return null;
  // Kenya FY: July–June
  const y = d.getFullYear();
  const m = d.getMonth(); // 0-indexed
  return m >= 6 ? `${y}/${y+1}` : `${y-1}/${y}`;
};

const allFYs = records => {
  const s = new Set();
  records.forEach(r => { const f = fyOf(r.date); if (f) s.add(f); });
  return Array.from(s).sort().reverse();
};

const fyRange = fy => {
  if (!fy) return null;
  const [a] = fy.split("/");
  return { start: `${a}-07-01`, end: `${Number(a)+1}-06-30` };
};

/* ─── top-level component ───────────────────────────────────── */
const TABS = [
  { id:"revenue",    label:"Revenue Performance",     icon:"ti-trending-up" },
  { id:"collection", label:"Collection Efficiency",    icon:"ti-target" },
  { id:"insurance",  label:"Insurance Claims",         icon:"ti-shield-check" },
  { id:"service",    label:"Revenue by Service",       icon:"ti-layout-grid" },
  { id:"channel",    label:"Payment Channels",         icon:"ti-credit-card" },
  { id:"waivers",    label:"Waivers & Discounts",      icon:"ti-discount" },
  { id:"patients",   label:"Patient Analytics",        icon:"ti-users" },
  { id:"dept",       label:"Department Performance",   icon:"ti-building-hospital" },
];

export default function Analytics() {
  const [records,  setRecords]  = useState([]);
  const [claims,   setClaims]   = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [tab,      setTab]      = useState("revenue");

  /* filters */
  const [fStart,   setFStart]   = useState("");
  const [fEnd,     setFEnd]     = useState("");
  const [fFY,      setFFY]      = useState("");
  const [fStream,  setFStream]  = useState("All");
  const [fChannel, setFChannel] = useState("All");
  const [fType,    setFType]    = useState("All");    // Inpatient/Outpatient
  const [fWard,    setFWard]    = useState("All");
  const [fScheme,  setFScheme]  = useState("All");

  useEffect(() => {
    const uRev = onSnapshot(query(collection(db,"revenue"), orderBy("date","asc")), snap => {
      setRecords(snap.docs.map(d => ({ id:d.id, ...d.data() })));
      setLoading(false);
    });
    const uClaim = onSnapshot(query(collection(db,"insurance_claims"), orderBy("date","asc")), snap => {
      setClaims(snap.docs.map(d => ({ id:d.id, ...d.data() })));
    });
    return () => { uRev(); uClaim(); };
  }, []);

  /* apply filters */
  const filtered = useMemo(() => {
    let r = records;
    if (fFY) {
      const rng = fyRange(fFY);
      if (rng) r = r.filter(x => x.date >= rng.start && x.date <= rng.end);
    } else {
      if (fStart) r = r.filter(x => x.date >= fStart);
      if (fEnd)   r = r.filter(x => x.date <= fEnd);
    }
    if (fStream  !== "All") r = r.filter(x => x.stream === fStream);
    if (fChannel !== "All") r = r.filter(x => channelOf(x) === fChannel);
    if (fType    !== "All") r = r.filter(x => (x.admissionType||"Outpatient") === fType);
    if (fWard    !== "All") r = r.filter(x => x.ward === fWard);
    return r;
  }, [records, fFY, fStart, fEnd, fStream, fChannel, fType, fWard]);

  const filteredClaims = useMemo(() => {
    let c = claims;
    if (fFY) {
      const rng = fyRange(fFY);
      if (rng) c = c.filter(x => x.date >= rng.start && x.date <= rng.end);
    } else {
      if (fStart) c = c.filter(x => x.date >= fStart);
      if (fEnd)   c = c.filter(x => x.date <= fEnd);
    }
    if (fScheme !== "All") c = c.filter(x => x.scheme === fScheme);
    return c;
  }, [claims, fFY, fStart, fEnd, fScheme]);

  /* global KPIs */
  const totalRevenue   = filtered.reduce((s,r) => s+(r.totalBill||0), 0);
  const totalCollected = filtered.reduce((s,r) => s+(r.amountPaid||0), 0);
  const totalWaived    = filtered.reduce((s,r) => s+(r.amountWaived||0), 0);
  const totalOutstanding = filtered.reduce((s,r) => s+(r.balance||0), 0);
  const claimsValue    = filteredClaims.reduce((s,c) => s+(c.claimAmount||0), 0);
  const collectionRate = totalRevenue ? (totalCollected/totalRevenue*100).toFixed(1) : 0;
  const waiverPct      = totalRevenue ? (totalWaived/totalRevenue*100).toFixed(1) : 0;
  const fyOptions      = allFYs(records);
  const streamOptions  = ["All",...new Set(records.map(r=>r.stream).filter(Boolean))];
  const wardOptions    = ["All",...new Set(records.map(r=>r.ward).filter(Boolean))];

  if (loading) return <Spinner />;

  return (
    <div style={{ fontFamily:"inherit" }}>
      {/* ── PAGE TITLE ── */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:20 }}>
        <p style={{ fontWeight:700, fontSize:20, margin:0, color:NAVY }}>Analytics</p>
        <span style={{ fontSize:11, color:GRAY }}>{filtered.length} records · {filteredClaims.length} claims</span>
      </div>

      {/* ── GLOBAL FILTERS ── */}
      <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1rem 1.25rem", marginBottom:20 }}>
        <p style={{ fontSize:11, fontWeight:600, color:GRAY, textTransform:"uppercase", letterSpacing:"0.06em", margin:"0 0 10px" }}>Filters</p>
        <div style={{ display:"flex", flexWrap:"wrap", gap:10, alignItems:"flex-end" }}>
          {/* Financial Year */}
          <div>
            <label style={lbl}>Financial Year</label>
            <select style={sel} value={fFY} onChange={e=>{setFFY(e.target.value);setFStart("");setFEnd("");}}>
              <option value="">All years</option>
              {fyOptions.map(f=><option key={f}>{f}</option>)}
            </select>
          </div>
          {/* Date range */}
          <div>
            <label style={lbl}>From</label>
            <input type="date" style={sel} value={fStart} onChange={e=>{setFStart(e.target.value);setFFY("");}} />
          </div>
          <div>
            <label style={lbl}>To</label>
            <input type="date" style={sel} value={fEnd} onChange={e=>{setFEnd(e.target.value);setFFY("");}} />
          </div>
          {/* Stream */}
          <div>
            <label style={lbl}>Service</label>
            <select style={sel} value={fStream} onChange={e=>setFStream(e.target.value)}>
              {streamOptions.map(s=><option key={s}>{s}</option>)}
            </select>
          </div>
          {/* Channel */}
          <div>
            <label style={lbl}>Payment Channel</label>
            <select style={sel} value={fChannel} onChange={e=>setFChannel(e.target.value)}>
              {["All","Cash","M-PESA","Insurance","Bank","Other"].map(c=><option key={c}>{c}</option>)}
            </select>
          </div>
          {/* Patient type */}
          <div>
            <label style={lbl}>Patient Type</label>
            <select style={sel} value={fType} onChange={e=>setFType(e.target.value)}>
              {["All","Inpatient","Outpatient"].map(t=><option key={t}>{t}</option>)}
            </select>
          </div>
          {/* Ward */}
          <div>
            <label style={lbl}>Ward</label>
            <select style={sel} value={fWard} onChange={e=>setFWard(e.target.value)}>
              {wardOptions.map(w=><option key={w}>{w}</option>)}
            </select>
          </div>
          {/* Insurance */}
          <div>
            <label style={lbl}>Insurance</label>
            <select style={sel} value={fScheme} onChange={e=>setFScheme(e.target.value)}>
              {["All",...INSURANCE_SCHEMES].map(s=><option key={s}>{s}</option>)}
            </select>
          </div>
          {(fFY||fStart||fEnd||fStream!=="All"||fChannel!=="All"||fType!=="All"||fWard!=="All"||fScheme!=="All") && (
            <button onClick={()=>{setFFY("");setFStart("");setFEnd("");setFStream("All");setFChannel("All");setFType("All");setFWard("All");setFScheme("All");}}
              style={{ padding:"6px 12px", fontSize:11, borderRadius:6, border:"1px solid #fca5a5", background:"#fef2f2", color:"#dc2626", cursor:"pointer", alignSelf:"flex-end" }}>
              Clear filters
            </button>
          )}
        </div>
      </div>

      {/* ── TOP KPI CARDS ── */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))", gap:12, marginBottom:20 }}>
        <KpiCard label="Total Billed"       value={fmtShort(totalRevenue)}    icon="ti-file-dollar"     accent={NAVY}   />
        <KpiCard label="Total Collected"    value={fmtShort(totalCollected)}  icon="ti-circle-check"    accent={GREEN}  />
        <KpiCard label="Outstanding"        value={fmtShort(totalOutstanding)} icon="ti-clock"          accent={RED}    />
        <KpiCard label="Claims Value"       value={fmtShort(claimsValue)}     icon="ti-shield-check"    accent={PURPLE} />
        <KpiCard label="Collection Rate"    value={collectionRate+"%"}        icon="ti-trending-up"     accent={TEAL}   />
        <KpiCard label="Waivers"            value={waiverPct+"%"}             icon="ti-discount"        accent={GOLD}   sub={fmtShort(totalWaived)} />
      </div>

      {/* ── TABS ── */}
      <div style={{ display:"flex", gap:4, flexWrap:"wrap", marginBottom:20 }}>
        {TABS.map(t => (
          <button key={t.id} onClick={()=>setTab(t.id)} style={{
            display:"flex", alignItems:"center", gap:6, padding:"7px 14px", fontSize:12,
            borderRadius:8, border:`1px solid ${tab===t.id?NAVY:"#e5e7eb"}`,
            background: tab===t.id ? NAVY : "#fff",
            color: tab===t.id ? "#fff" : GRAY,
            fontWeight: tab===t.id ? 600 : 400, cursor:"pointer", transition:"all 0.15s"
          }}>
            <i className={`ti ${t.icon}`} style={{ fontSize:13 }} />
            {t.label}
          </button>
        ))}
      </div>

      {/* ── TAB PANELS ── */}
      {tab === "revenue"    && <RevenuePerformance records={filtered} />}
      {tab === "collection" && <CollectionEfficiency records={filtered} />}
      {tab === "insurance"  && <InsuranceClaims claims={filteredClaims} />}
      {tab === "service"    && <RevenueByService records={filtered} />}
      {tab === "channel"    && <PaymentChannels records={filtered} />}
      {tab === "waivers"    && <WaiversDiscounts records={filtered} />}
      {tab === "patients"   && <PatientAnalytics records={filtered} />}
      {tab === "dept"       && <DepartmentPerformance records={filtered} claims={filteredClaims} />}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   1. REVENUE PERFORMANCE
═══════════════════════════════════════════════════════════════ */
function RevenuePerformance({ records }) {
  const [period, setPeriod] = useState("monthly");

  const monthly = useMemo(() => {
    const m = {};
    records.forEach(r => {
      const k = (r.date||"").slice(0,7); if (!k) return;
      if (!m[k]) m[k] = { period:k, billed:0, collected:0, waived:0 };
      m[k].billed    += r.totalBill   || 0;
      m[k].collected += r.amountPaid  || 0;
      m[k].waived    += r.amountWaived|| 0;
    });
    return Object.values(m).sort((a,b)=>a.period.localeCompare(b.period));
  }, [records]);

  const quarterly = useMemo(() => {
    const q = {};
    records.forEach(r => {
      const d = new Date(r.date); if (isNaN(d)) return;
      const k = `${d.getFullYear()} Q${Math.floor(d.getMonth()/3)+1}`;
      if (!q[k]) q[k] = { period:k, billed:0, collected:0, waived:0 };
      q[k].billed    += r.totalBill   || 0;
      q[k].collected += r.amountPaid  || 0;
      q[k].waived    += r.amountWaived|| 0;
    });
    return Object.values(q).sort((a,b)=>a.period.localeCompare(b.period));
  }, [records]);

  const annual = useMemo(() => {
    const a = {};
    records.forEach(r => {
      const fy = fyOf(r.date); if (!fy) return;
      if (!a[fy]) a[fy] = { period:fy, billed:0, collected:0, waived:0 };
      a[fy].billed    += r.totalBill   || 0;
      a[fy].collected += r.amountPaid  || 0;
      a[fy].waived    += r.amountWaived|| 0;
    });
    return Object.values(a).sort((a,b)=>a.period.localeCompare(b.period));
  }, [records]);

  const data = period==="quarterly" ? quarterly : period==="annual" ? annual : monthly;

  /* cumulative */
  let cum = 0;
  const cumData = data.map(d => { cum += d.collected; return { ...d, cumulative: cum }; });

  /* insights */
  const best = [...monthly].sort((a,b)=>b.collected-a.collected)[0];
  const prevM = monthly.length >= 2 ? monthly[monthly.length-2] : null;
  const currM = monthly.length >= 1 ? monthly[monthly.length-1] : null;
  const growth = prevM && prevM.collected ? (((currM.collected-prevM.collected)/prevM.collected)*100).toFixed(1) : null;

  if (!records.length) return <EmptyTab />;

  return (
    <div>
      <div style={{ display:"flex", gap:6, marginBottom:16 }}>
        {["monthly","quarterly","annual"].map(p=>(
          <button key={p} onClick={()=>setPeriod(p)} style={periodBtn(period===p)}>{p.charAt(0).toUpperCase()+p.slice(1)}</button>
        ))}
      </div>

      {/* Insight chips */}
      <div style={{ display:"flex", gap:10, flexWrap:"wrap", marginBottom:16 }}>
        {best && <InsightChip label="Best Month" value={`${best.period} — ${fmtShort(best.collected)}`} color={GREEN} />}
        {growth !== null && <InsightChip label="MoM Growth" value={`${growth>0?"+":""}${growth}%`} color={Number(growth)>=0?GREEN:RED} />}
        <InsightChip label="Records" value={records.length} color={NAVY} />
      </div>

      {/* Line: revenue trends */}
      <ChartCard title="Revenue Trend">
        <ResponsiveContainer width="100%" height={240}>
          <LineChart data={cumData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
            <XAxis dataKey="period" tick={{ fontSize:10 }} />
            <YAxis tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
            <Tooltip formatter={v=>fmt(v)} />
            <Legend wrapperStyle={{ fontSize:11 }} />
            <Line type="monotone" dataKey="billed"    name="Billed"    stroke={NAVY}  strokeWidth={2} dot={false} />
            <Line type="monotone" dataKey="collected" name="Collected" stroke={GREEN} strokeWidth={2} dot={false} />
          </LineChart>
        </ResponsiveContainer>
      </ChartCard>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginTop:16 }}>
        {/* Bar: monthly comparison */}
        <ChartCard title="Period Comparison">
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={data}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="period" tick={{ fontSize:9 }} />
              <YAxis tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
              <Tooltip formatter={v=>fmt(v)} />
              <Legend wrapperStyle={{ fontSize:11 }} />
              <Bar dataKey="billed"    name="Billed"    fill={NAVY}  radius={[3,3,0,0]} />
              <Bar dataKey="collected" name="Collected" fill={GREEN} radius={[3,3,0,0]} />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Area: cumulative growth */}
        <ChartCard title="Cumulative Collections">
          <ResponsiveContainer width="100%" height={220}>
            <AreaChart data={cumData}>
              <defs>
                <linearGradient id="cumGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%"  stopColor={NAVY} stopOpacity={0.2}/>
                  <stop offset="95%" stopColor={NAVY} stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="period" tick={{ fontSize:9 }} />
              <YAxis tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
              <Tooltip formatter={v=>fmt(v)} />
              <Area type="monotone" dataKey="cumulative" name="Cumulative" stroke={NAVY} fill="url(#cumGrad)" strokeWidth={2} />
            </AreaChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   2. COLLECTION EFFICIENCY
═══════════════════════════════════════════════════════════════ */
function CollectionEfficiency({ records }) {
  const totalBilled    = records.reduce((s,r)=>s+(r.totalBill||0),0);
  const totalCollected = records.reduce((s,r)=>s+(r.amountPaid||0),0);
  const totalWaived    = records.reduce((s,r)=>s+(r.amountWaived||0),0);
  const outstanding    = records.reduce((s,r)=>s+(r.balance||0),0);
  const rate           = totalBilled ? (totalCollected/totalBilled*100).toFixed(1) : 0;

  /* paid vs unpaid */
  const paid    = records.filter(r=>(r.balance||0)<=0).length;
  const unpaid  = records.filter(r=>(r.balance||0)>0).length;
  const donutData = [
    { name:"Fully Paid",   value:paid,   fill:GREEN },
    { name:"Outstanding",  value:unpaid, fill:RED   },
  ];

  /* aging buckets */
  const today = new Date();
  const aging = { "0–30":0, "31–60":0, "61–90":0, "90+":0 };
  const agingAmt = { "0–30":0, "31–60":0, "61–90":0, "90+":0 };
  records.filter(r=>(r.balance||0)>0).forEach(r => {
    const days = Math.floor((today - new Date(r.date))/86400000);
    const b    = r.balance||0;
    if (days<=30)      { aging["0–30"]++;  agingAmt["0–30"]+=b; }
    else if (days<=60) { aging["31–60"]++; agingAmt["31–60"]+=b; }
    else if (days<=90) { aging["61–90"]++; agingAmt["61–90"]+=b; }
    else               { aging["90+"]++;   agingAmt["90+"]+=b; }
  });

  const agingRows = Object.entries(aging).map(([k,v])=>({ bucket:k, records:v, amount:agingAmt[k] }));

  /* gauge data */
  const gaugeData = [{ name:"Rate", value:Number(rate), fill:rate>=80?GREEN:rate>=60?GOLD:RED }];

  if (!records.length) return <EmptyTab />;

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))", gap:12, marginBottom:16 }}>
        <KpiCard label="Collection Rate"    value={rate+"%"}             accent={Number(rate)>=80?GREEN:Number(rate)>=60?GOLD:RED} icon="ti-target" />
        <KpiCard label="Total Outstanding"  value={fmtShort(outstanding)} accent={RED}   icon="ti-clock" />
        <KpiCard label="Fully Paid Records" value={paid}                  accent={GREEN} icon="ti-circle-check" />
        <KpiCard label="Outstanding Records" value={unpaid}               accent={RED}   icon="ti-alert-circle" />
        <KpiCard label="Waived"             value={fmtShort(totalWaived)} accent={GOLD}  icon="ti-discount" />
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:16 }}>
        {/* Gauge */}
        <ChartCard title="Collection Rate Gauge">
          <div style={{ position:"relative", display:"flex", flexDirection:"column", alignItems:"center", paddingTop:8 }}>
            <ResponsiveContainer width="100%" height={160}>
              <RadialBarChart cx="50%" cy="75%" innerRadius="60%" outerRadius="90%" barSize={18} data={gaugeData} startAngle={180} endAngle={0}>
                <RadialBar dataKey="value" cornerRadius={6} />
                <PolarAngleAxis type="number" domain={[0,100]} angleAxisId={0} tick={false} />
              </RadialBarChart>
            </ResponsiveContainer>
            <div style={{ position:"absolute", bottom:8, textAlign:"center" }}>
              <div style={{ fontSize:28, fontWeight:700, color:gaugeData[0].fill }}>{rate}%</div>
              <div style={{ fontSize:11, color:GRAY }}>Collection Rate</div>
            </div>
          </div>
        </ChartCard>

        {/* Donut */}
        <ChartCard title="Paid vs Outstanding (Records)">
          <ResponsiveContainer width="100%" height={180}>
            <PieChart>
              <Pie data={donutData} cx="50%" cy="50%" innerRadius={50} outerRadius={75} paddingAngle={3} dataKey="value">
                {donutData.map((d,i)=><Cell key={i} fill={d.fill} />)}
              </Pie>
              <Tooltip formatter={v=>`${v} records`} />
              <Legend wrapperStyle={{ fontSize:11 }} />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      {/* Aging table */}
      <ChartCard title="Outstanding Aging Analysis">
        <table style={{ width:"100%", fontSize:12, borderCollapse:"collapse" }}>
          <thead>
            <tr>
              {["Age Bucket","Outstanding Records","Outstanding Amount","% of Total Outstanding"].map(h=>(
                <th key={h} style={{ padding:"8px 12px", textAlign:h==="Age Bucket"?"left":"right", fontSize:11, fontWeight:600, color:GRAY, borderBottom:"1px solid #f3f4f6" }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {agingRows.map(r=>(
              <tr key={r.bucket} style={{ borderBottom:"1px solid #f9fafb" }}>
                <td style={{ padding:"10px 12px", fontWeight:500 }}>
                  <span style={{ background: r.bucket==="90+"?"#fef2f2":r.bucket==="61–90"?"#fff7ed":r.bucket==="31–60"?"#fefce8":"#f0fdf4",
                    color: r.bucket==="90+"?RED:r.bucket==="61–90"?"#c2410c":r.bucket==="31–60"?"#854d0e":GREEN,
                    padding:"2px 8px", borderRadius:10, fontSize:11 }}>{r.bucket} days</span>
                </td>
                <td style={{ padding:"10px 12px", textAlign:"right" }}>{r.records}</td>
                <td style={{ padding:"10px 12px", textAlign:"right", fontWeight:500 }}>{fmt(r.amount)}</td>
                <td style={{ padding:"10px 12px", textAlign:"right", color:GRAY }}>{outstanding?((r.amount/outstanding)*100).toFixed(1)+"%":"—"}</td>
              </tr>
            ))}
            <tr style={{ borderTop:"2px solid #e5e7eb", fontWeight:600 }}>
              <td style={{ padding:"10px 12px", color:NAVY }}>Total</td>
              <td style={{ padding:"10px 12px", textAlign:"right" }}>{unpaid}</td>
              <td style={{ padding:"10px 12px", textAlign:"right", color:RED }}>{fmt(outstanding)}</td>
              <td style={{ padding:"10px 12px", textAlign:"right" }}>100%</td>
            </tr>
          </tbody>
        </table>
      </ChartCard>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   3. INSURANCE CLAIMS ANALYTICS
═══════════════════════════════════════════════════════════════ */
function InsuranceClaims({ claims }) {
  const submitted = claims.length;
  const approved  = claims.filter(c=>["Approved","Paid"].includes(c.status)).length;
  const paid      = claims.filter(c=>c.status==="Paid").length;
  const rejected  = claims.filter(c=>c.status==="Rejected").length;
  const pending   = claims.filter(c=>["Submitted","Under Review"].includes(c.status)).length;
  const total     = claims.reduce((s,c)=>s+(c.claimAmount||0),0);
  const approvedAmt = claims.filter(c=>["Approved","Paid"].includes(c.status)).reduce((s,c)=>s+(c.claimAmount||0),0);

  /* status donut */
  const statusData = CLAIM_STATUSES.map(st=>({
    name:st, value:claims.filter(c=>c.status===st).length, fill:CLAIM_STATUS_COLORS[st]
  })).filter(d=>d.value>0);

  /* by scheme stacked */
  const byScheme = INSURANCE_SCHEMES.map((s,i) => {
    const sc = claims.filter(c=>c.scheme===s);
    return {
      scheme:s,
      Submitted:  sc.filter(c=>c.status==="Submitted").length,
      "Under Review": sc.filter(c=>c.status==="Under Review").length,
      Approved:   sc.filter(c=>["Approved","Paid"].includes(c.status)).length,
      Rejected:   sc.filter(c=>c.status==="Rejected").length,
      amount:     sc.reduce((a,c)=>a+(c.claimAmount||0),0),
    };
  }).filter(s=>s.amount>0||s.Submitted>0);

  /* funnel */
  const funnelData = [
    { name:"Submitted",    value:submitted,                     fill:GOLD   },
    { name:"Under Review", value:claims.filter(c=>c.status!=="Submitted").length, fill:PURPLE },
    { name:"Approved",     value:approved, fill:GREEN  },
    { name:"Paid",         value:paid,     fill:NAVY   },
  ];

  /* monthly trend */
  const mMap = {};
  claims.forEach(c=>{
    const k=(c.date||"").slice(0,7); if(!k) return;
    if(!mMap[k]) mMap[k]={month:k,amount:0,count:0};
    mMap[k].amount+=c.claimAmount||0; mMap[k].count++;
  });
  const mTrend = Object.values(mMap).sort((a,b)=>a.month.localeCompare(b.month));

  if (!claims.length) return <EmptyTab msg="No insurance claims in this period." />;

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))", gap:12, marginBottom:16 }}>
        <KpiCard label="Submitted"   value={submitted}         accent={GOLD}   icon="ti-send" />
        <KpiCard label="Approved"    value={approved}          accent={GREEN}  icon="ti-circle-check" />
        <KpiCard label="Paid"        value={paid}              accent={NAVY}   icon="ti-cash" />
        <KpiCard label="Rejected"    value={rejected}          accent={RED}    icon="ti-x" />
        <KpiCard label="Pending"     value={pending}           accent={PURPLE} icon="ti-clock" />
        <KpiCard label="Total Value" value={fmtShort(total)}   accent={TEAL}   icon="ti-file-dollar" />
        <KpiCard label="Approved Value" value={fmtShort(approvedAmt)} accent={GREEN} icon="ti-check" />
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:16 }}>
        {/* Status donut */}
        <ChartCard title="Claims by Status">
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie data={statusData} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={3} dataKey="value">
                {statusData.map((d,i)=><Cell key={i} fill={d.fill} />)}
              </Pie>
              <Tooltip formatter={v=>`${v} claims`} />
              <Legend wrapperStyle={{ fontSize:11 }} />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Funnel */}
        <ChartCard title="Claims Funnel">
          <ResponsiveContainer width="100%" height={200}>
            <FunnelChart>
              <Tooltip formatter={v=>`${v} claims`} />
              <Funnel dataKey="value" data={funnelData} isAnimationActive>
                <LabelList position="center" fill="#fff" style={{ fontSize:11, fontWeight:600 }}
                  formatter={(v,entry)=>`${entry?.name}: ${v}`} />
                {funnelData.map((d,i)=><Cell key={i} fill={d.fill} />)}
              </Funnel>
            </FunnelChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      {/* By scheme stacked bar */}
      {byScheme.length > 0 && (
        <ChartCard title="Claims by Insurance Scheme">
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={byScheme}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="scheme" tick={{ fontSize:10 }} />
              <YAxis allowDecimals={false} tick={{ fontSize:10 }} />
              <Tooltip />
              <Legend wrapperStyle={{ fontSize:11 }} />
              <Bar dataKey="Submitted"    stackId="a" fill={GOLD}   />
              <Bar dataKey="Under Review" stackId="a" fill={PURPLE} />
              <Bar dataKey="Approved"     stackId="a" fill={GREEN}  />
              <Bar dataKey="Rejected"     stackId="a" fill={RED}    />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>
      )}

      {/* Monthly trend */}
      {mTrend.length > 1 && (
        <ChartCard title="Monthly Claims Trend" style={{ marginTop:16 }}>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={mTrend}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="month" tick={{ fontSize:10 }} />
              <YAxis tickFormatter={v=>`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
              <Tooltip formatter={v=>fmt(v)} />
              <Bar dataKey="amount" name="Claim Amount" fill={NAVY} radius={[4,4,0,0]} />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   4. REVENUE BY SERVICE
═══════════════════════════════════════════════════════════════ */
function RevenueByService({ records }) {
  const total = records.reduce((s,r)=>s+(r.amountPaid||0),0);
  const byService = Object.entries(
    records.reduce((acc,r) => {
      const s=r.stream||"Other";
      acc[s]=(acc[s]||0)+(r.amountPaid||0);
      return acc;
    },{})
  ).map(([name,value])=>({ name, value, pct:total?(value/total*100).toFixed(1):"0" }))
   .sort((a,b)=>b.value-a.value);

  const treemapData = byService.map((s,i)=>({ ...s, fill:STREAM_COLORS[s.name]||GRAY }));

  if (!records.length) return <EmptyTab />;

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:16 }}>
        {/* Horizontal bar */}
        <ChartCard title="Revenue by Service (Horizontal Bar)">
          <ResponsiveContainer width="100%" height={Math.max(200, byService.length*40+40)}>
            <BarChart data={byService} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis type="number" tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
              <YAxis type="category" dataKey="name" tick={{ fontSize:11 }} width={100} />
              <Tooltip formatter={v=>fmt(v)} />
              <Bar dataKey="value" name="Revenue" radius={[0,4,4,0]}>
                {byService.map((s,i)=><Cell key={i} fill={STREAM_COLORS[s.name]||GRAY} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Pie */}
        <ChartCard title="Contribution Analysis">
          <ResponsiveContainer width="100%" height={220}>
            <PieChart>
              <Pie data={byService} cx="50%" cy="50%" outerRadius={80} dataKey="value" label={({name,pct})=>`${name}: ${pct}%`} labelLine={false}>
                {byService.map((s,i)=><Cell key={i} fill={STREAM_COLORS[s.name]||GRAY} />)}
              </Pie>
              <Tooltip formatter={v=>fmt(v)} />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      {/* Treemap */}
      {byService.length > 1 && (
        <ChartCard title="Revenue Treemap">
          <ResponsiveContainer width="100%" height={220}>
            <Treemap data={treemapData} dataKey="value" aspectRatio={4/3} stroke="#fff" content={<CustomTreemapContent />} />
          </ResponsiveContainer>
        </ChartCard>
      )}

      {/* Insights */}
      <div style={{ display:"flex", gap:10, flexWrap:"wrap", marginTop:16 }}>
        {byService[0] && <InsightChip label="Highest Earning" value={`${byService[0].name} — ${fmtShort(byService[0].value)}`} color={GREEN} />}
        {byService[byService.length-1]?.value < byService[0]?.value * 0.05 &&
          <InsightChip label="Low Performer" value={byService[byService.length-1]?.name} color={RED} />}
      </div>
    </div>
  );
}

const CustomTreemapContent = ({ x, y, width, height, name, value, fill }) => {
  if (!width || !height || width < 30 || height < 20) return null;
  return (
    <g>
      <rect x={x} y={y} width={width} height={height} style={{ fill, stroke:"#fff", strokeWidth:2 }} />
      {width > 60 && height > 30 && (
        <>
          <text x={x+width/2} y={y+height/2-6} textAnchor="middle" fill="#fff" fontSize={10} fontWeight={600}>{name}</text>
          <text x={x+width/2} y={y+height/2+10} textAnchor="middle" fill="rgba(255,255,255,0.8)" fontSize={9}>{fmtShort(value)}</text>
        </>
      )}
    </g>
  );
};

/* ═══════════════════════════════════════════════════════════════
   5. PAYMENT CHANNELS
═══════════════════════════════════════════════════════════════ */
function PaymentChannels({ records }) {
  const channels = ["Cash","M-PESA","Insurance","Bank","Other"];
  const total = records.reduce((s,r)=>s+(r.amountPaid||0),0);

  const byChannel = channels.map(ch => ({
    name:ch,
    value:  records.filter(r=>channelOf(r)===ch).reduce((s,r)=>s+(r.amountPaid||0),0),
    count:  records.filter(r=>channelOf(r)===ch).length,
    fill:   CHANNEL_COLORS[ch],
  })).filter(c=>c.value>0||c.count>0);

  /* monthly by channel */
  const mMap = {};
  records.forEach(r => {
    const k=(r.date||"").slice(0,7); if(!k) return;
    const ch=channelOf(r);
    if(!mMap[k]) { mMap[k]={month:k}; channels.forEach(c=>{mMap[k][c]=0;}); }
    mMap[k][ch]=(mMap[k][ch]||0)+(r.amountPaid||0);
  });
  const mTrend = Object.values(mMap).sort((a,b)=>a.month.localeCompare(b.month));

  if (!records.length) return <EmptyTab />;

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(130px,1fr))", gap:12, marginBottom:16 }}>
        {byChannel.map(c=>(
          <KpiCard key={c.name} label={c.name} value={fmtShort(c.value)} sub={`${c.count} records · ${total?(c.value/total*100).toFixed(1):0}%`} accent={c.fill} icon="ti-credit-card" />
        ))}
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:16 }}>
        {/* Donut */}
        <ChartCard title="Channel Distribution">
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie data={byChannel} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={3} dataKey="value">
                {byChannel.map((c,i)=><Cell key={i} fill={c.fill} />)}
              </Pie>
              <Tooltip formatter={v=>fmt(v)} />
              <Legend wrapperStyle={{ fontSize:11 }} />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Bar: daily average */}
        <ChartCard title="Revenue per Channel">
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={byChannel} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis type="number" tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
              <YAxis type="category" dataKey="name" tick={{ fontSize:11 }} width={80} />
              <Tooltip formatter={v=>fmt(v)} />
              <Bar dataKey="value" name="Revenue" radius={[0,4,4,0]}>
                {byChannel.map((c,i)=><Cell key={i} fill={c.fill} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      {/* Stacked monthly */}
      {mTrend.length > 1 && (
        <ChartCard title="Channel Trends (Monthly)">
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={mTrend}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="month" tick={{ fontSize:10 }} />
              <YAxis tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
              <Tooltip formatter={v=>fmt(v)} />
              <Legend wrapperStyle={{ fontSize:11 }} />
              {channels.map(ch=><Bar key={ch} dataKey={ch} stackId="a" fill={CHANNEL_COLORS[ch]} />)}
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   6. WAIVERS & DISCOUNTS
═══════════════════════════════════════════════════════════════ */
function WaiversDiscounts({ records }) {
  const waivedRecords = records.filter(r=>(r.amountWaived||0)>0);
  const totalWaived   = waivedRecords.reduce((s,r)=>s+(r.amountWaived||0),0);
  const totalBilled   = records.reduce((s,r)=>s+(r.totalBill||0),0);
  const waiverPct     = totalBilled ? (totalWaived/totalBilled*100).toFixed(1) : 0;

  /* by stream */
  const byStream = Object.entries(
    waivedRecords.reduce((acc,r)=>{
      const s=r.stream||"Other";
      acc[s]=(acc[s]||0)+(r.amountWaived||0);
      return acc;
    },{})
  ).map(([name,value])=>({ name, value })).sort((a,b)=>b.value-a.value);

  /* monthly */
  const mMap = {};
  waivedRecords.forEach(r=>{
    const k=(r.date||"").slice(0,7); if(!k) return;
    if(!mMap[k]) mMap[k]={month:k,waived:0,records:0};
    mMap[k].waived+=r.amountWaived||0; mMap[k].records++;
  });
  const mTrend = Object.values(mMap).sort((a,b)=>a.month.localeCompare(b.month));

  /* by user who entered — use createdBy or patientName as proxy */
  const byCreator = Object.entries(
    waivedRecords.reduce((acc,r)=>{
      const u=r.createdByName||r.createdBy||"Unknown";
      if(!acc[u]) acc[u]={amount:0,count:0};
      acc[u].amount+=r.amountWaived||0; acc[u].count++;
      return acc;
    },{})
  ).map(([name,v])=>({name,...v})).sort((a,b)=>b.amount-a.amount).slice(0,8);

  if (!records.length) return <EmptyTab />;

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(130px,1fr))", gap:12, marginBottom:16 }}>
        <KpiCard label="Total Waived"    value={fmtShort(totalWaived)} accent={GOLD}  icon="ti-discount" />
        <KpiCard label="Waiver Records"  value={waivedRecords.length}  accent={PURPLE} icon="ti-file" />
        <KpiCard label="% Revenue Waived" value={waiverPct+"%"}        accent={RED}   icon="ti-trending-down" />
        <KpiCard label="Avg per Record"  value={waivedRecords.length?fmtShort(totalWaived/waivedRecords.length):"—"} accent={TEAL} icon="ti-calculator" />
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:16 }}>
        {/* Waivers by stream */}
        <ChartCard title="Waivers by Service">
          {byStream.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={byStream} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
                <XAxis type="number" tickFormatter={v=>v>=1e3?`${(v/1e3).toFixed(0)}K`:v} tick={{ fontSize:10 }} />
                <YAxis type="category" dataKey="name" tick={{ fontSize:11 }} width={100} />
                <Tooltip formatter={v=>fmt(v)} />
                <Bar dataKey="value" name="Waived" fill={GOLD} radius={[0,4,4,0]} />
              </BarChart>
            </ResponsiveContainer>
          ) : <EmptyChart />}
        </ChartCard>

        {/* Monthly waiver trend */}
        <ChartCard title="Waiver Trend (Monthly)">
          {mTrend.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <AreaChart data={mTrend}>
                <defs>
                  <linearGradient id="waiverGrad" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%"  stopColor={GOLD} stopOpacity={0.3} />
                    <stop offset="95%" stopColor={GOLD} stopOpacity={0}   />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
                <XAxis dataKey="month" tick={{ fontSize:10 }} />
                <YAxis tickFormatter={v=>v>=1e3?`${(v/1e3).toFixed(0)}K`:v} tick={{ fontSize:10 }} />
                <Tooltip formatter={v=>fmt(v)} />
                <Area type="monotone" dataKey="waived" name="Waived" stroke={GOLD} fill="url(#waiverGrad)" strokeWidth={2} />
              </AreaChart>
            </ResponsiveContainer>
          ) : <EmptyChart />}
        </ChartCard>
      </div>

      {/* Staff waiver table */}
      {byCreator.length > 0 && (
        <ChartCard title="Waivers by Staff">
          <table style={{ width:"100%", fontSize:12, borderCollapse:"collapse" }}>
            <thead>
              <tr>{["Staff","Waiver Records","Total Waived","Avg Waiver"].map(h=>(
                <th key={h} style={{ padding:"8px 12px", textAlign:h==="Staff"?"left":"right", fontSize:11, fontWeight:600, color:GRAY, borderBottom:"1px solid #f3f4f6" }}>{h}</th>
              ))}</tr>
            </thead>
            <tbody>
              {byCreator.map(s=>(
                <tr key={s.name} style={{ borderBottom:"1px solid #f9fafb" }}>
                  <td style={{ padding:"9px 12px" }}>{s.name}</td>
                  <td style={{ padding:"9px 12px", textAlign:"right" }}>{s.count}</td>
                  <td style={{ padding:"9px 12px", textAlign:"right", fontWeight:500 }}>{fmt(s.amount)}</td>
                  <td style={{ padding:"9px 12px", textAlign:"right", color:GRAY }}>{fmt(s.count?s.amount/s.count:0)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </ChartCard>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   7. PATIENT ANALYTICS
═══════════════════════════════════════════════════════════════ */
function PatientAnalytics({ records }) {
  const patientMap = {};
  records.forEach(r => {
    const key = r.patientNo || r.patientName || "Unknown";
    if (!patientMap[key]) patientMap[key] = { name:r.patientName||key, no:r.patientNo||"", visits:0, revenue:0, types:new Set() };
    patientMap[key].visits++;
    patientMap[key].revenue += r.amountPaid||0;
    patientMap[key].types.add(r.admissionType||"Outpatient");
  });

  const patients      = Object.values(patientMap);
  const totalRevenue  = patients.reduce((s,p)=>s+p.revenue,0);
  const uniquePatients = patients.length;
  const repeatPatients = patients.filter(p=>p.visits>1).length;
  const avgRevPerPat  = uniquePatients ? totalRevenue/uniquePatients : 0;

  const inpatients  = records.filter(r=>(r.admissionType||"Outpatient")==="Inpatient").length;
  const outpatients = records.filter(r=>(r.admissionType||"Outpatient")==="Outpatient").length;
  const ipRev = records.filter(r=>(r.admissionType||"Outpatient")==="Inpatient").reduce((s,r)=>s+(r.amountPaid||0),0);
  const opRev = records.filter(r=>(r.admissionType||"Outpatient")==="Outpatient").reduce((s,r)=>s+(r.amountPaid||0),0);

  const typeData = [
    { name:"Inpatient",  records:inpatients,  revenue:ipRev, fill:NAVY  },
    { name:"Outpatient", records:outpatients, revenue:opRev, fill:GREEN },
  ];

  /* top patients by revenue */
  const topPatients = [...patients].sort((a,b)=>b.revenue-a.revenue).slice(0,10);

  if (!records.length) return <EmptyTab />;

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(130px,1fr))", gap:12, marginBottom:16 }}>
        <KpiCard label="Unique Patients" value={uniquePatients}       accent={NAVY}   icon="ti-users" />
        <KpiCard label="Repeat Patients" value={repeatPatients}       accent={GREEN}  icon="ti-repeat" sub={uniquePatients?`${(repeatPatients/uniquePatients*100).toFixed(0)}% of patients`:""} />
        <KpiCard label="Revenue/Patient" value={fmtShort(avgRevPerPat)} accent={GOLD} icon="ti-coin" />
        <KpiCard label="Inpatients"      value={inpatients}            accent={PURPLE} icon="ti-bed" />
        <KpiCard label="Outpatients"     value={outpatients}           accent={TEAL}   icon="ti-walk" />
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:16 }}>
        {/* Inpatient vs Outpatient records */}
        <ChartCard title="Inpatient vs Outpatient (Records)">
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie data={typeData} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={3} dataKey="records">
                {typeData.map((d,i)=><Cell key={i} fill={d.fill} />)}
              </Pie>
              <Tooltip formatter={v=>`${v} records`} />
              <Legend wrapperStyle={{ fontSize:11 }} />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Inpatient vs Outpatient revenue */}
        <ChartCard title="Inpatient vs Outpatient (Revenue)">
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie data={typeData} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={3} dataKey="revenue">
                {typeData.map((d,i)=><Cell key={i} fill={d.fill} />)}
              </Pie>
              <Tooltip formatter={v=>fmt(v)} />
              <Legend wrapperStyle={{ fontSize:11 }} />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      {/* Top patients */}
      <ChartCard title="Top 10 Patients by Revenue">
        <table style={{ width:"100%", fontSize:12, borderCollapse:"collapse" }}>
          <thead>
            <tr>{["#","Patient","Patient No.","Visits","Revenue","Type"].map(h=>(
              <th key={h} style={{ padding:"8px 12px", textAlign:h==="Revenue"?"right":"left", fontSize:11, fontWeight:600, color:GRAY, borderBottom:"1px solid #f3f4f6" }}>{h}</th>
            ))}</tr>
          </thead>
          <tbody>
            {topPatients.map((p,i)=>(
              <tr key={p.name+i} style={{ borderBottom:"1px solid #f9fafb" }}>
                <td style={{ padding:"9px 12px", color:GRAY, fontWeight:600 }}>#{i+1}</td>
                <td style={{ padding:"9px 12px", fontWeight:500 }}>{p.name}</td>
                <td style={{ padding:"9px 12px", color:GRAY }}>{p.no||"—"}</td>
                <td style={{ padding:"9px 12px" }}>{p.visits}</td>
                <td style={{ padding:"9px 12px", textAlign:"right", fontWeight:600, color:NAVY }}>{fmt(p.revenue)}</td>
                <td style={{ padding:"9px 12px" }}>
                  {[...p.types].map(t=>(
                    <span key={t} style={{ background:t==="Inpatient"?"#dbeafe":"#dcfce7", color:t==="Inpatient"?NAVY:GREEN, padding:"2px 7px", borderRadius:10, fontSize:10, marginRight:3 }}>{t}</span>
                  ))}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </ChartCard>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   8. DEPARTMENT PERFORMANCE
═══════════════════════════════════════════════════════════════ */
function DepartmentPerformance({ records, claims }) {
  /* group by ward (for inpatients) + stream (for outpatients treated as dept) */
  const deptMap = {};
  const addDept = (key, r) => {
    if (!deptMap[key]) deptMap[key]={ dept:key, billed:0, collected:0, waived:0, outstanding:0, records:0 };
    deptMap[key].billed      += r.totalBill   ||0;
    deptMap[key].collected   += r.amountPaid  ||0;
    deptMap[key].waived      += r.amountWaived||0;
    deptMap[key].outstanding += r.balance     ||0;
    deptMap[key].records++;
  };
  records.forEach(r => {
    const key = r.admissionType==="Inpatient" && r.ward ? r.ward : (r.stream||"Other");
    addDept(key, r);
  });

  const depts = Object.values(deptMap).sort((a,b)=>b.collected-a.collected);

  /* claims by scheme for dept comparison */
  const claimsByScheme = INSURANCE_SCHEMES.map(s=>({
    scheme:s,
    count: claims.filter(c=>c.scheme===s).length,
    amount:claims.filter(c=>c.scheme===s).reduce((a,c)=>a+(c.claimAmount||0),0),
  })).filter(s=>s.count>0);

  if (!records.length) return <EmptyTab />;

  return (
    <div>
      {/* Bar: collected by dept */}
      <ChartCard title="Revenue Collected by Department / Service">
        <ResponsiveContainer width="100%" height={Math.max(200, depts.length*38+50)}>
          <BarChart data={depts} layout="vertical">
            <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
            <XAxis type="number" tickFormatter={v=>v>=1e6?`${(v/1e6).toFixed(1)}M`:`${(v/1e3).toFixed(0)}K`} tick={{ fontSize:10 }} />
            <YAxis type="category" dataKey="dept" tick={{ fontSize:11 }} width={120} />
            <Tooltip formatter={v=>fmt(v)} />
            <Legend wrapperStyle={{ fontSize:11 }} />
            <Bar dataKey="collected"   name="Collected"   stackId="a" fill={GREEN} radius={[0,4,4,0]} />
            <Bar dataKey="outstanding" name="Outstanding" stackId="a" fill={RED}   radius={[0,4,4,0]} />
          </BarChart>
        </ResponsiveContainer>
      </ChartCard>

      {/* Scorecard table */}
      <ChartCard title="Department Scorecards" style={{ marginTop:16 }}>
        <div style={{ overflowX:"auto" }}>
          <table style={{ width:"100%", fontSize:12, borderCollapse:"collapse", minWidth:600 }}>
            <thead>
              <tr>{["Department","Records","Billed","Collected","Outstanding","Waived","Rate"].map(h=>(
                <th key={h} style={{ padding:"9px 12px", textAlign:h==="Department"?"left":"right", fontSize:11, fontWeight:600, color:GRAY, borderBottom:"2px solid #e5e7eb", whiteSpace:"nowrap" }}>{h}</th>
              ))}</tr>
            </thead>
            <tbody>
              {depts.map((d,i)=>{
                const rate = d.billed?(d.collected/d.billed*100).toFixed(1):0;
                return (
                  <tr key={d.dept} style={{ borderBottom:"1px solid #f3f4f6", background:i%2===0?"#fff":"#f9fafb" }}>
                    <td style={{ padding:"9px 12px", fontWeight:500 }}>{d.dept}</td>
                    <td style={{ padding:"9px 12px", textAlign:"right", color:GRAY }}>{d.records}</td>
                    <td style={{ padding:"9px 12px", textAlign:"right" }}>{fmt(d.billed)}</td>
                    <td style={{ padding:"9px 12px", textAlign:"right", fontWeight:600, color:GREEN }}>{fmt(d.collected)}</td>
                    <td style={{ padding:"9px 12px", textAlign:"right", color:RED }}>{d.outstanding>0?fmt(d.outstanding):"—"}</td>
                    <td style={{ padding:"9px 12px", textAlign:"right", color:GOLD }}>{d.waived>0?fmt(d.waived):"—"}</td>
                    <td style={{ padding:"9px 12px", textAlign:"right" }}>
                      <span style={{ background:rate>=80?"#dcfce7":rate>=60?"#fef9c3":"#fee2e2", color:rate>=80?GREEN:rate>=60?"#854d0e":RED, padding:"2px 8px", borderRadius:10, fontSize:11, fontWeight:600 }}>{rate}%</span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </ChartCard>

      {/* Claims by scheme */}
      {claimsByScheme.length > 0 && (
        <ChartCard title="Insurance Claims Volume by Scheme" style={{ marginTop:16 }}>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={claimsByScheme}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="scheme" tick={{ fontSize:10 }} />
              <YAxis tick={{ fontSize:10 }} />
              <Tooltip formatter={(v,name)=>name==="amount"?fmt(v):v} />
              <Legend wrapperStyle={{ fontSize:11 }} />
              <Bar dataKey="count"  name="No. of Claims" fill={NAVY}  radius={[4,4,0,0]} yAxisId={0} />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>
      )}
    </div>
  );
}

/* ─── shared mini-components ─────────────────────────────────── */
function KpiCard({ label, value, icon, accent, sub }) {
  return (
    <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1rem", borderLeft:`3px solid ${accent}` }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
        <div>
          <p style={{ fontSize:10, fontWeight:600, color:GRAY, textTransform:"uppercase", letterSpacing:"0.06em", margin:"0 0 4px" }}>{label}</p>
          <p style={{ fontSize:18, fontWeight:700, color:"#111", margin:0 }}>{value}</p>
          {sub && <p style={{ fontSize:10, color:GRAY, margin:"2px 0 0" }}>{sub}</p>}
        </div>
        {icon && <i className={`ti ${icon}`} style={{ fontSize:20, color:accent, opacity:0.7 }} />}
      </div>
    </div>
  );
}

function ChartCard({ title, children, style }) {
  return (
    <div style={{ background:"#fff", border:"1px solid #e5e7eb", borderRadius:12, padding:"1.25rem", ...style }}>
      <p style={{ fontSize:13, fontWeight:600, color:NAVY, margin:"0 0 1rem" }}>{title}</p>
      {children}
    </div>
  );
}

function InsightChip({ label, value, color }) {
  return (
    <div style={{ display:"flex", alignItems:"center", gap:6, background:`${color}12`, border:`1px solid ${color}33`, borderRadius:8, padding:"5px 12px" }}>
      <span style={{ fontSize:10, fontWeight:600, color, textTransform:"uppercase", letterSpacing:"0.05em" }}>{label}:</span>
      <span style={{ fontSize:12, fontWeight:600, color:"#111" }}>{value}</span>
    </div>
  );
}

function EmptyTab({ msg }) {
  return (
    <div style={{ textAlign:"center", padding:"4rem 2rem", color:GRAY }}>
      <i className="ti ti-chart-bar" style={{ fontSize:40, display:"block", marginBottom:10 }} />
      <p>{msg||"No data available for this period. Add revenue records to see analytics."}</p>
    </div>
  );
}

function EmptyChart() {
  return <div style={{ display:"flex", alignItems:"center", justifyContent:"center", height:140, color:GRAY, fontSize:12 }}>No data</div>;
}

function Spinner() {
  return (
    <div style={{ display:"flex", justifyContent:"center", padding:"5rem" }}>
      <div style={{ width:36, height:36, border:"3px solid #e5e7eb", borderTopColor:NAVY, borderRadius:"50%", animation:"spin 0.8s linear infinite" }} />
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

